('db067593-d407-58e5-8353-68674a362526','610e74af-d183-5847-978f-30dd61e5f18f',1,'noun','B2','S2','W2',null,'[{"phrase":"take somebody into your confidence","register":null,"definition_en":"to tell someone your secrets or private or personal details about your life","translation":"رازها یا جزئیات خصوصی یا شخصی خود را در مورد زندگی خود به کسی بگویید","example":"Elsa took me into her confidence and told me about some of the problems she was facing.","example_translation":"السا مرا با اعتماد به نفس خود گرفت و در مورد برخی از مشکلاتی که با آن روبرو بود به من گفت.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001717356.mp3"}]'::jsonb),
