('69e1cacb-bce4-5622-af15-504a86e4239b','c3c63956-f4b6-59ae-be24-0a24654ef160',1,null,null,'spoken & written','the time in the middle of the day when people usually eat their lunch',null,null,'وقت ناهار، زمان ناهار','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Some people prefer to eat their main meal at lunchtime.","translation":"برخی از افراد ترجیح می دهند وعده غذایی اصلی خود را در زمان ناهار بخورند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001739602.mp3"},{"sentence":"a lunchtime drink","translation":"یک نوشیدنی برای ناهار","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001474837.mp3"}]'::jsonb,2),
