('70dfd686-840d-54cc-ad8b-6e6896ff8f9c','d45fe93c-79ab-531d-82d4-52ad8b2c2527',1,null,null,'spoken & written','to discuss something in order to reach an agreement , especially in business or politics','[ intransitive, transitive ]',null,'مذاکره کردن؛ چانه زدن؛ رهگیری (مسیر خطرناک)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The government refuses to negotiate with terrorists.","translation":"دولت حاضر به مذاکره با تروریست ها نیست.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000238201.mp3"},{"sentence":"Union leaders have negotiated an agreement for a shorter working week.","translation":"رهبران اتحادیه ها برای یک هفته کاری کوتاه تر بر سر توافقی مذاکره کرده اند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000238204.mp3"},{"sentence":"His first aim is to get the warring parties back to the negotiating table (= discussing something ) .","translation":"اولین هدف او بازگرداندن طرف های متخاصم به میز مذاکره (= بحث در مورد چیزی) است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000238208.mp3"},{"sentence":"The two sides have to negotiate.","translation":"دو طرف باید مذاکره کنند.","audio_url":null},{"sentence":"The two sides have to negotiate with each other.","translation":"دو طرف باید با یکدیگر مذاکره کنند.","audio_url":null},{"sentence":"One side has to negotiate with the other.","translation":"یک طرف باید با طرف دیگر مذاکره کند.","audio_url":null}]'::jsonb,6),
('c1684a7e-9786-5758-85c2-16b35b5c0eb8','d45fe93c-79ab-531d-82d4-52ad8b2c2527',2,null,null,'spoken & written','to succeed in getting past or over a difficult place on a path , road etc','[ transitive ]',null,'موفقیت در عبور از یک مکان دشوار در مسیر، جاده و غیره','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Guido swung the steering-wheel round to negotiate a corner.","translation":"گیدو فرمان را چرخاند تا در یک گوشه مذاکره کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000238213.mp3"}]'::jsonb,1),
('d49258b1-8654-5d1f-ad34-6c768b0ebb56','e9a4e202-367a-5b27-a44b-8f7a7bd0b507',1,null,null,'spoken & written','someone who lives next to you or near you',null,null,'همسایه، همسایگان (خانه)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"One of the neighbors complained about the noise from the party.","translation":"یکی از همسایه ها از سر و صدای مهمانی شکایت کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001712332.mp3"},{"sentence":"FBI agents were interviewing all their friends and neighbors.","translation":"ماموران اف بی آی در حال مصاحبه با دوستان و همسایگان خود بودند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001760685.mp3"},{"sentence":"Our next-door neighbours (= the people who live in the house next to us ) say they’ll look after our cat for us while we’re away.","translation":"همسایه های همسایه ما (= افرادی که در خانه کنار ما زندگی می کنند) می گویند تا زمانی که ما دور هستیم از گربه ما مراقبت می کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001712333.mp3"}]'::jsonb,3),
('f2c1b94f-05d7-5279-a1cc-8ea7337c35a0','e9a4e202-367a-5b27-a44b-8f7a7bd0b507',2,null,null,'spoken & written','a country that is next to another one',null,null,'کشوری که در کنار کشور دیگری است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Israel and its Arab neighbours","translation":"اسرائیل و همسایگان عرب آن","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001712346.mp3"}]'::jsonb,1),
('1fb07a02-fb6d-5a0c-a4b7-85ab9ddd5b0d','e9a4e202-367a-5b27-a44b-8f7a7bd0b507',3,null,null,'spoken & written','someone or something that is next to another person or thing of the same type',null,null,'کسی یا چیزی که در کنار شخص یا چیزی از همان نوع است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The teacher saw Phil passing a note to his neighbour.","translation":"معلم فیل را دید که یادداشتی را به همسایه اش می دهد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000238862.mp3"},{"sentence":"The garden was divided from its neighbour by a high wall.","translation":"باغ با دیوار بلندی از همسایه اش جدا شده بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001712347.mp3"}]'::jsonb,2),
('c188f3c9-778f-5879-b988-d28b5ea3c641','42f0a73a-e13b-5827-ae79-997db52d8147',1,null,null,'spoken & written','a set of large folded sheets of printed paper containing news , articles , pictures , advertisements etc which is sold daily or weekly','[ countable ]',null,'روزنامه، جریده',array['paper']::text[],'{}'::text[],array['read a newspaper Which newspaper do you read?','get a newspaper (= buy one regularly ) We don’t get a newspaper; we tend to watch the news on TV.','see/read something in the newspaper I saw in the newspaper that he had died.','appear in a newspaper Her photo appeared in all the newspapers.','a newspaper reports something (= has an article on something ) The newspapers reported that the police were treating the death as a suicide.','a national newspaper The story was in all the national newspapers.','a local newspaper The store advertises in the local newspaper.','a daily/weekly/Sunday newspaper (= one that is published every day/week/Sunday ) Do you get a daily newspaper?','a tabloid newspaper (= a small-sized newspaper, especially one with not much serious news ) Their wedding made the headlines in all the tabloid newspapers.','a quality newspaper British English (= a newspaper with a lot of serious news and good writing ) The story has not been given as much coverage in the quality newspapers.','a newspaper article/report/story I read quite an interesting newspaper report on the war.','a newspaper headline ‘Wine is good for you’ announced a recent newspaper headline.','a newspaper column (= a regular article in a newspaper written by a particular journalist ) She writes a regular newspaper column about gardening.','a newspaper clipping/cutting (= a story cut out of a newspaper ) I found some old newspaper cuttings of the band''s first concert in Liverpool.','a newspaper reporter She was fed up with being followed by newspaper reporters.','a newspaper editor Newspaper editors have a lot of power.','a newspaper proprietor British English (= owner ) Ultimately, it’s the newspaper proprietor who decides what goes into the newspaper.']::text[],'[{"sentence":"She had read about it in the newspaper.","translation":"او در مورد آن در روزنامه خوانده بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa001096.mp3"},{"sentence":"a series of newspaper articles about life in Cuba","translation":"مجموعه ای از مقالات روزنامه در مورد زندگی در کوبا","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa001097.mp3"},{"sentence":"I saw an ad in the paper .","translation":"من یک آگهی در روزنامه دیدم.","audio_url":null}]'::jsonb,3),
('77066ba2-f092-527e-96d4-d3b8c26e9637','42f0a73a-e13b-5827-ae79-997db52d8147',2,null,null,'spoken & written','sheets of paper from old newspapers','[ uncountable ]',null,'ورق های کاغذ از روزنامه های قدیمی','{}'::text[],'{}'::text[],array['read a newspaper Which newspaper do you read?','get a newspaper (= buy one regularly ) We don’t get a newspaper; we tend to watch the news on TV.','see/read something in the newspaper I saw in the newspaper that he had died.','appear in a newspaper Her photo appeared in all the newspapers.','a newspaper reports something (= has an article on something ) The newspapers reported that the police were treating the death as a suicide.','a national newspaper The story was in all the national newspapers.','a local newspaper The store advertises in the local newspaper.','a daily/weekly/Sunday newspaper (= one that is published every day/week/Sunday ) Do you get a daily newspaper?','a tabloid newspaper (= a small-sized newspaper, especially one with not much serious news ) Their wedding made the headlines in all the tabloid newspapers.','a quality newspaper British English (= a newspaper with a lot of serious news and good writing ) The story has not been given as much coverage in the quality newspapers.','a newspaper article/report/story I read quite an interesting newspaper report on the war.','a newspaper headline ‘Wine is good for you’ announced a recent newspaper headline.','a newspaper column (= a regular article in a newspaper written by a particular journalist ) She writes a regular newspaper column about gardening.','a newspaper clipping/cutting (= a story cut out of a newspaper ) I found some old newspaper cuttings of the band''s first concert in Liverpool.','a newspaper reporter She was fed up with being followed by newspaper reporters.','a newspaper editor Newspaper editors have a lot of power.','a newspaper proprietor British English (= owner ) Ultimately, it’s the newspaper proprietor who decides what goes into the newspaper.']::text[],'[{"sentence":"Wrap the plates in newspaper to stop them from breaking.","translation":"بشقاب ها را در روزنامه بپیچید تا از شکستن آن ها جلوگیری کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000241093.mp3"},{"sentence":"Bella laid the flowers out carefully on a sheet of newspaper .","translation":"بلا گلها را با دقت روی یک برگه روزنامه گذاشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001556607.mp3"}]'::jsonb,2),
('6d94be48-312b-5935-b02c-46ecb56998d1','42f0a73a-e13b-5827-ae79-997db52d8147',3,null,null,'spoken & written','a company that produces a newspaper','[ countable ]',null,'شرکتی که روزنامه تولید می کند','{}'::text[],'{}'::text[],array['read a newspaper Which newspaper do you read?','get a newspaper (= buy one regularly ) We don’t get a newspaper; we tend to watch the news on TV.','see/read something in the newspaper I saw in the newspaper that he had died.','appear in a newspaper Her photo appeared in all the newspapers.','a newspaper reports something (= has an article on something ) The newspapers reported that the police were treating the death as a suicide.','a national newspaper The story was in all the national newspapers.','a local newspaper The store advertises in the local newspaper.','a daily/weekly/Sunday newspaper (= one that is published every day/week/Sunday ) Do you get a daily newspaper?','a tabloid newspaper (= a small-sized newspaper, especially one with not much serious news ) Their wedding made the headlines in all the tabloid newspapers.','a quality newspaper British English (= a newspaper with a lot of serious news and good writing ) The story has not been given as much coverage in the quality newspapers.','a newspaper article/report/story I read quite an interesting newspaper report on the war.','a newspaper headline ‘Wine is good for you’ announced a recent newspaper headline.','a newspaper column (= a regular article in a newspaper written by a particular journalist ) She writes a regular newspaper column about gardening.','a newspaper clipping/cutting (= a story cut out of a newspaper ) I found some old newspaper cuttings of the band''s first concert in Liverpool.','a newspaper reporter She was fed up with being followed by newspaper reporters.','a newspaper editor Newspaper editors have a lot of power.','a newspaper proprietor British English (= owner ) Ultimately, it’s the newspaper proprietor who decides what goes into the newspaper.']::text[],'[{"sentence":"He works for a local newspaper.","translation":"او برای یک روزنامه محلی کار می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000241099.mp3"}]'::jsonb,1),
('11842170-a521-5fc9-be28-549931fba6c2','70b0aacb-9c4d-56eb-ae6c-a3fa72d1e1fd',1,null,null,'spoken & written','a reason that you have for opposing or disapproving of something, or something you say that expresses this','[ countable, uncountable ]',null,'اعتراض، مخالفت؛ عذر (اعتراض)','{}'::text[],'{}'::text[],array['have an objection Does anyone have any objections to the proposal?','make an objection (= say what your objection is ) The Parish Council made several objections to the changes.','raise/voice an objection (= make an objection ) His father raised no objections when John told him that he wanted to become a dancer.','meet somebody’s objections (= change something so that someone will no longer object ) He altered the plans to meet the objections of community leaders.','withdraw an objection (= stop objecting to something ) The FBI withdrew its objections to publishing the information.','lodge an objection (= formally make an objection ) Residents have lodged an objection to the new development.','a strong objection Parents at the school have voiced strong objections to the closure.','a serious/major objection There were serious objections to using the videotaped evidence at the trial.','the main objection One of the main objections was that classes were being taught by untrained staff.','a fundamental objection A fundamental objection is that the church should not be part of the government.','a moral objection He has expressed moral objections to this type of research.','a religious objection Roman Catholics have religious objections to the use of contraceptives.','(a) conscientious objection (= the fact of refusing to become a solider because of your moral or religious beliefs ) Conscientious objection to military service is seen by the United Nations as part of your right to freedom of thought.']::text[],'[{"sentence":"Her objection was that he was too young.","translation":"اعتراض او این بود که او خیلی جوان است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001557396.mp3"},{"sentence":"He had moral objections to killing animals for food.","translation":"او با کشتن حیوانات برای غذا مخالفت های اخلاقی داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa001113.mp3"},{"sentence":"The bill was passed over the objections of many Democrats.","translation":"این لایحه با مخالفت بسیاری از دموکرات ها به تصویب رسید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa001114.mp3"}]'::jsonb,3),
('9c63e151-be9c-5dc5-9557-b2f0cfba9b00','70b0aacb-9c4d-56eb-ae6c-a3fa72d1e1fd',2,null,null,'spoken & written',null,null,'objection!','اعتراض، مخالفت؛ عذر (اعتراض)','{}'::text[],'{}'::text[],array['have an objection Does anyone have any objections to the proposal?','make an objection (= say what your objection is ) The Parish Council made several objections to the changes.','raise/voice an objection (= make an objection ) His father raised no objections when John told him that he wanted to become a dancer.','meet somebody’s objections (= change something so that someone will no longer object ) He altered the plans to meet the objections of community leaders.','withdraw an objection (= stop objecting to something ) The FBI withdrew its objections to publishing the information.','lodge an objection (= formally make an objection ) Residents have lodged an objection to the new development.','a strong objection Parents at the school have voiced strong objections to the closure.','a serious/major objection There were serious objections to using the videotaped evidence at the trial.','the main objection One of the main objections was that classes were being taught by untrained staff.','a fundamental objection A fundamental objection is that the church should not be part of the government.','a moral objection He has expressed moral objections to this type of research.','a religious objection Roman Catholics have religious objections to the use of contraceptives.','(a) conscientious objection (= the fact of refusing to become a solider because of your moral or religious beliefs ) Conscientious objection to military service is seen by the United Nations as part of your right to freedom of thought.']::text[],'[]'::jsonb,0),
('0411fa5f-e71b-5a0d-abbc-92571c3d50a1','42f23659-017d-5ad8-979a-d5f130800dc9',1,null,null,'spoken formal','said by lawyers to a judge in a court when they think that what another lawyer has just said should not be allowed',null,null,'زمانی که وکلا به قاضی در دادگاه می گویند وقتی فکر می کنند آنچه وکیل دیگری گفته نباید مجاز باشد','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('f146df8b-e383-558b-968a-174aa9a70bde','c37d2fe9-f3ed-55cb-b483-e9a80c385f9e',1,null,null,'spoken & written','something that you are trying hard to achieve , especially in business or politics',null,null,'هدف، مقصود؛ مؤثر (صفت)؛ عینی (فلسفه)',array['goal']::text[],'{}'::text[],array['have an objective Our main objective is to reduce road accidents.','set an objective (= decide what you are trying to achieve ) Pupils should be encouraged to set their own objectives.','achieve/accomplish an objective ( also attain an objective formal ) The policy should help us achieve our objective of reducing paper waste.','reach/meet an objective (= achieve an objective ) We need to control spending in order to meet our financial objectives.','pursue an objective (= try to achieve something you want ) War has always been a means of pursuing national objectives.','the main/principal objective This research project has three main objectives.','the primary/prime objective (= the main one ) The primary objective of training is to improve performance.','a key objective (= a very important objective ) Their economic strategy was based on a number of key objectives.','a clear objective A manager must give his team clear objectives to work towards.','a specific objective Most classroom activities have a specific learning objective.','a stated objective (= what someone says their objective is ) The city’s stated objective was to improve housing in the area.','a common objective (= one that people, countries etc share ) Our employees have a sense of common objectives and their commitment is high.','an economic/military/business/political etc objective We have made good progress towards meeting our business objectives.','aims and objectives (= all the things someone wants to achieve ) The department should clearly state its aims and objectives.']::text[],'[{"sentence":"He vowed to achieve certain objectives before the end of his presidency.","translation":"او قول داد قبل از پایان دوره ریاست جمهوری خود به اهداف خاصی دست یابد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001557411.mp3"},{"sentence":"the best way to accomplish your objectives","translation":"بهترین راه برای رسیدن به اهداف","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001557417.mp3"},{"sentence":"The degree program has two main objectives .","translation":"برنامه مدرک دو هدف اصلی دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001969969.mp3"},{"sentence":"Managers should set specific performance objectives for their teams.","translation":"مدیران باید اهداف عملکردی خاصی را برای تیم خود تعیین کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa001115.mp3"},{"sentence":"The main objective was to improve children’s knowledge of geography.","translation":"هدف اصلی این بود که دانش جغرافیایی کودکان را بهبود بخشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001969981.mp3"},{"sentence":"A clear objective was set and adhered to.","translation":"هدف مشخصی تعیین شد و به آن پایبند بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001969985.mp3"},{"sentence":"One of your first business objectives should be to get your own office.","translation":"یکی از اولین اهداف تجاری شما باید این باشد که دفتر کار خود را داشته باشید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa001116.mp3"}]'::jsonb,7),
('d4fc7044-c224-52ef-b3e0-721c79f687b5','c37d2fe9-f3ed-55cb-b483-e9a80c385f9e',2,null,null,'spoken & written','a place that you are trying to reach , especially in a military attack',null,null,'مکانی که شما در حال تلاش برای رسیدن به آن هستید، به خصوص در یک حمله نظامی','{}'::text[],'{}'::text[],array['have an objective Our main objective is to reduce road accidents.','set an objective (= decide what you are trying to achieve ) Pupils should be encouraged to set their own objectives.','achieve/accomplish an objective ( also attain an objective formal ) The policy should help us achieve our objective of reducing paper waste.','reach/meet an objective (= achieve an objective ) We need to control spending in order to meet our financial objectives.','pursue an objective (= try to achieve something you want ) War has always been a means of pursuing national objectives.','the main/principal objective This research project has three main objectives.','the primary/prime objective (= the main one ) The primary objective of training is to improve performance.','a key objective (= a very important objective ) Their economic strategy was based on a number of key objectives.','a clear objective A manager must give his team clear objectives to work towards.','a specific objective Most classroom activities have a specific learning objective.','a stated objective (= what someone says their objective is ) The city’s stated objective was to improve housing in the area.','a common objective (= one that people, countries etc share ) Our employees have a sense of common objectives and their commitment is high.','an economic/military/business/political etc objective We have made good progress towards meeting our business objectives.','aims and objectives (= all the things someone wants to achieve ) The department should clearly state its aims and objectives.']::text[],'[{"sentence":"The 4th Division’s objective was a town 20 miles to the east.","translation":"هدف لشکر چهارم شهری در 20 مایلی شرق بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa020136.mp3"}]'::jsonb,1),
('c744dc3b-8b78-586d-80cf-81c2d149648e','178aead6-060a-55b3-b167-aa4cb34ad2d7',1,null,null,'spoken & written','based on facts, or making a decision that is based on facts rather than on your feelings or beliefs',null,null,'بر اساس حقایق، یا تصمیم گیری بر اساس واقعیت ها و نه بر اساس احساسات یا باورهای شما','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"It’s hard to give an objective opinion about your own children.","translation":"اظهار نظر عینی در مورد فرزندان خود سخت است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001759940.mp3"},{"sentence":"Scientists need to be objective when doing research.","translation":"دانشمندان باید هنگام انجام تحقیقات عینی باشند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001557418.mp3"},{"sentence":"the importance of a completely objective, independent press","translation":"اهمیت یک مطبوعات کاملاً عینی و مستقل","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001557422.mp3"}]'::jsonb,3),
('9f3bbb03-f47f-516d-b756-870a74766a42','178aead6-060a-55b3-b167-aa4cb34ad2d7',2,null,null,'formal','existing outside the mind as something real , not only as an idea',null,null,'وجود خارج از ذهن به عنوان چیزی واقعی، نه تنها به عنوان یک ایده','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The world has an objective reality.","translation":"جهان یک واقعیت عینی دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000256709.mp3"}]'::jsonb,1),
('1a440081-94ea-5942-ac13-3e54b39ddd77','862d8241-74a4-579d-a3f3-205c6f04325f',1,null,null,'spoken & written','used to mean that a fact can easily be noticed or understood',null,null,'بدیهی است، واضح است؛ حتماً (تأکید)',array['clearly']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We’re obviously going to need more help.","translation":"بدیهی است که به کمک بیشتری نیاز خواهیم داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000258023.mp3"},{"sentence":"Your research has obviously been very thorough.","translation":"تحقیقات شما واضح است که بسیار کامل بوده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000258024.mp3"},{"sentence":"Obviously, this is going to take some time.","translation":"بدیهی است که این امر مدتی طول خواهد کشید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001760124.mp3"},{"sentence":"Cost is obviously important.","translation":"هزینه آشکارا مهم است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001536186.mp3"},{"sentence":"She frowned and was obviously puzzled.","translation":"اخم کرد و معلوم بود که گیج شده بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001536187.mp3"}]'::jsonb,5),
('7e0bc11d-a639-5d44-b43e-450444a21fb7','7c31bc5a-dac6-58a1-b4a0-d007343694f7',1,null,null,'spoken & written','used to show that other people probably already know what you are saying is true , or expect to hear it',null,null,'البته، طبیعتاً؛ البته (تأکید)؛ حتماً','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Well, she won, of course.","translation":"خوب، او البته برنده شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000259672.mp3"},{"sentence":"You should of course keep copies of all your correspondence.","translation":"البته باید از تمام مکاتبات خود کپی نگه دارید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000259671.mp3"},{"sentence":"Of course there will be some difficult times ahead.","translation":"البته روزهای سختی در راه است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001762044.mp3"}]'::jsonb,3),
('c6c3d985-2fba-57d0-939f-0b58d9ac5dc2','7c31bc5a-dac6-58a1-b4a0-d007343694f7',2,null,null,'spoken','used to emphasize that you are saying ‘ yes ’ when someone asks your permission to do something',null,null,'زمانی که شخصی برای انجام کاری از شما اجازه می‌خواهد، تأکید می‌کند که «بله» می‌گویید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"‘Can I ring you back in a minute?’ ‘Yes, of course.’","translation":"«می‌توانم یک دقیقه دیگر به شما زنگ بزنم؟» «بله، البته.»","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001535801.mp3"},{"sentence":"‘Is it OK if I have another cup of coffee?’ ‘Course, help yourself.’","translation":"\"اگر من یک فنجان قهوه دیگر بخورم اشکالی ندارد؟\" \"البته، به خودت کمک کن.\"","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001535802.mp3"}]'::jsonb,2),
('69192867-588a-5028-ba5b-cae4ada2214a','7c31bc5a-dac6-58a1-b4a0-d007343694f7',3,null,null,'spoken','used to emphasize that what you are saying to someone is true or correct',null,null,'برای تأکید بر اینکه آنچه به کسی می گویید درست یا درست است استفاده می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"‘Do you really believe her?’ ‘Of course I do!’","translation":"«واقعاً او را باور داری؟» «البته که باور دارم!»","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001535811.mp3"},{"sentence":"‘I hope this idea of yours works.’ ‘Course it’ll work.’","translation":"\"امیدوارم این ایده شما کار کند.\" \"البته که کار خواهد کرد.\"","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001535812.mp3"}]'::jsonb,2),
('ffe6a06e-13e4-533e-a7e1-1c9245fbbc72','7c31bc5a-dac6-58a1-b4a0-d007343694f7',4,null,null,'spoken','used to show that you accept or agree with what someone has just said',null,null,'برای نشان دادن اینکه شما آنچه را که یک نفر اخیراً گفته است قبول دارید یا موافق هستید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"‘Don’t get angry. She’s only 13.’ ‘Of course.’","translation":"''عصبانی نشو. او فقط 13 سال دارد.» «البته.»","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa020138.mp3"},{"sentence":"‘The correct answer is 83.’ ‘Oh, yes, of course.’","translation":"«پاسخ صحیح 83 است.» «اوه، بله، البته.»","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001535818.mp3"}]'::jsonb,2),
('c5dbcb22-1396-508d-965e-f4f5d1057f5f','7c31bc5a-dac6-58a1-b4a0-d007343694f7',5,null,null,'spoken & written',null,null,'of course not/course not','البته، طبیعتاً؛ البته (تأکید)؛ حتماً','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('895ae98d-3cee-5a4c-ba2b-e35b532b3357','2675924b-9846-592e-85f5-93095d6be789',1,null,null,'informal','used to show that what you are saying is expected or already known and so not surprising',null,null,'استفاده می شود تا نشان دهد آنچه شما می گویید مورد انتظار یا از قبل شناخته شده است و بنابراین تعجب آور نیست','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"You can pay by cheque, assuming of course you have a valid cheque card.","translation":"البته با فرض داشتن کارت چک معتبر می توانید با چک پرداخت کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001114102.mp3"},{"sentence":"Of course there are exceptions to every rule.","translation":"البته برای هر قاعده ای استثنا وجود دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001680814.mp3"},{"sentence":"‘Can I have a word with you?’ ‘Of course.’","translation":"«می‌توانم با شما حرفی بزنم؟» «البته.»","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000385.mp3"},{"sentence":"‘Can you give me a lift?’ ‘Course, no problem.’","translation":"«می‌توانی به من کمک کنی؟» «مشکلی نیست.»","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000386.mp3"},{"sentence":"Of course he’ll come!","translation":"البته او خواهد آمد!","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001680822.mp3"},{"sentence":"Well of course I love you.","translation":"خب معلومه که دوستت دارم","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001680825.mp3"}]'::jsonb,6),
('8ee67dcf-320f-5d7a-86cd-0287d51c9554','47d87938-b305-57a4-abaa-51058ba061a9',1,'medical','پزشکی','spoken & written','the process of cutting into someone’s body to repair or remove a part that is damaged','[ countable ]',null,'عمل جراحی؛ عملیات (نظامی/شرکتی)؛ عمل (مکانیزم)','{}'::text[],'{}'::text[],array['have an operation ( also undergo an operation formal ) Harris had a hip operation in October. She has undergone 50 operations since birth.','do/carry out an operation ( also perform an operation formal ) The operation was carried out by a team of surgeons at Papworth Hospital. I’ve done this operation hundreds of times.','recover from an operation A man is recovering from an emergency operation after his pet dog attacked him.','survive an operation Only one person has survived an operation to implant an artificial heart.','a knee/heart/stomach etc operation He is almost back to full fitness after a knee operation.','a major/minor operation The unit cares for patients recovering from major operations.','an emergency operation He had to have his spleen removed in an emergency operation.','a routine operation (= an operation that is often performed ) a routine operation to remove an appendix','a life-saving operation The child underwent a life-saving operation to remove a blockage in her stomach.','a transplant operation He is too weak to undergo a transplant operation.']::text[],'[{"sentence":"She’s going to need an operation on her ankle.","translation":"او به عمل جراحی روی مچ پا نیاز دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000266682.mp3"},{"sentence":"an operation for cancer","translation":"یک عمل برای سرطان","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa001135.mp3"},{"sentence":"He had an operation to reduce the swelling in his brain.","translation":"او برای کاهش تورم مغزش عمل کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001536383.mp3"}]'::jsonb,3),
