('a62d8b7e-4ca0-592c-86fc-fad075721de9','3656d8b2-26b8-562a-be53-ad050f0162f8',1,null,null,'spoken & written','involving people working together in an effective and well-planned way',null,null,'سازمان‌یافته، منظم؛ (جرم) سازمان‌یافته','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Organized groups of citizens are more successful at changing the government’s mind.","translation":"گروه های سازمان یافته از شهروندان در تغییر نظر دولت موفق تر هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000379720.mp3"},{"sentence":"Organized networks of thieves are stealing cattle.","translation":"شبکه های سازمان یافته سارقان در حال سرقت احشام هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000379721.mp3"}]'::jsonb,2),
