('8d55b5be-8126-58ad-b0cd-7ce323c4b9cf','6d3ae71a-3c2f-5c6e-89a0-299e1389e754',1,null,null,'spoken & written','used by the person speaking to show that they and one or more other people are affected by their own action',null,null,'خودمان — ضمیر انعکاسی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We prepared ourselves for the long journey ahead.","translation":"ما خودمان را برای سفر طولانی پیش رو آماده کردیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001837572.mp3"},{"sentence":"It was strange seeing ourselves on television.","translation":"دیدن خودمان در تلویزیون عجیب بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000381369.mp3"}]'::jsonb,2),
('758d6eef-1ac4-5c88-a83f-e6c897ccddd0','6d3ae71a-3c2f-5c6e-89a0-299e1389e754',2,null,null,'spoken & written','used to emphasize ‘we’ or ‘us’',null,null,'برای تاکید بر "ما" یا "ما" استفاده می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We built the house ourselves.","translation":"خانه را خودمان ساختیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000381374.mp3"},{"sentence":"As parents ourselves, we understand the problem.","translation":"ما به عنوان والدین خود مشکل را درک می کنیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001837574.mp3"},{"sentence":"More help is needed for people like ourselves.","translation":"برای افرادی مثل خودمان به کمک بیشتری نیاز است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001837577.mp3"}]'::jsonb,3),
