('ad88c190-499e-533b-b9b6-0c64144c32d4','3cc70709-4058-5252-847a-bbe0217e9136',1,null,null,'spoken & written','the fact of owning something',null,null,'مالکیت، تملک؛ مالکیت (شخصی)؛ سند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a dispute over the ownership of the land","translation":"اختلاف بر سر مالکیت زمین","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000387648.mp3"},{"sentence":"The company was returned to private ownership in mid-1987.","translation":"این شرکت در اواسط سال 1987 به مالکیت خصوصی بازگردانده شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001764974.mp3"},{"sentence":"The price of home ownership is increasing.","translation":"قیمت مسکن در حال افزایش است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001824618.mp3"}]'::jsonb,3),
('2fa8403d-e2f8-53e6-9184-ef127e1ef61d','d257f0a1-990e-55ed-9299-e8fb64374caa',1,null,null,'spoken & written','someone who is travelling in a vehicle , plane , boat etc, but is not driving it or working on it',null,null,'مسافر، سرنشین؛ مسافر (اتوبوس)؛ سرنشین (هواپیما)','{}'::text[],'{}'::text[],array['carry passengers The aeroplane was carrying over 500 passengers.','passengers travel somewhere More than 7.6m rail passengers travelled on the Eurostar rail service last year.','passengers get on/off a bus/plane etc The bus stopped and half the passengers got off.','passengers board a plane/train formal (= get on it ) The first three cars were reserved for passengers boarding in Queens.','passengers are stranded (= are unable to continue their journey ) At least 1,000 passengers were stranded at the airport because of the storm.','rail passengers Rail passengers will have to pay more for their tickets next year.','airline passengers All airline passengers arriving at Heathrow must go through customs.','bus passengers Bus passengers are facing higher fares.','foot passengers (= passengers on a boat, who are not in a car or other vehicle ) A queue of foot passengers was waiting to get on the ferry.','a passenger train (= rather than a goods train ) The driver of the passenger train was unable to stop in time.','a passenger plane/jet It was recently converted from a passenger plane to cargo use.','a passenger ship It is the biggest passenger ship afloat.']::text[],'[{"sentence":"Neither the driver nor the passengers were hurt.","translation":"نه راننده و نه سرنشینان آسیب ندیده اند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000371269.mp3"},{"sentence":"a crash involving a passenger train","translation":"تصادف با قطار مسافربری","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001559406.mp3"},{"sentence":"Rail passengers now face even longer delays.","translation":"مسافران ریلی اکنون با تأخیر بیشتری مواجه هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001559412.mp3"}]'::jsonb,3),
('efc03768-a8ab-52fb-a46a-0e43c4df5d73','d257f0a1-990e-55ed-9299-e8fb64374caa',2,null,null,'spoken & written','someone in a group who does not do their share of the group’s work',null,null,'شخصی در یک گروه که سهم خود را از کار گروه انجام نمی دهد','{}'::text[],'{}'::text[],array['carry passengers The aeroplane was carrying over 500 passengers.','passengers travel somewhere More than 7.6m rail passengers travelled on the Eurostar rail service last year.','passengers get on/off a bus/plane etc The bus stopped and half the passengers got off.','passengers board a plane/train formal (= get on it ) The first three cars were reserved for passengers boarding in Queens.','passengers are stranded (= are unable to continue their journey ) At least 1,000 passengers were stranded at the airport because of the storm.','rail passengers Rail passengers will have to pay more for their tickets next year.','airline passengers All airline passengers arriving at Heathrow must go through customs.','bus passengers Bus passengers are facing higher fares.','foot passengers (= passengers on a boat, who are not in a car or other vehicle ) A queue of foot passengers was waiting to get on the ferry.','a passenger train (= rather than a goods train ) The driver of the passenger train was unable to stop in time.','a passenger plane/jet It was recently converted from a passenger plane to cargo use.','a passenger ship It is the biggest passenger ship afloat.']::text[],'[{"sentence":"The company can’t afford to carry any passengers.","translation":"این شرکت توانایی حمل مسافر را ندارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001559413.mp3"}]'::jsonb,1),
('6774c9f7-9d66-5890-965d-c60912ec6ee8','1222304d-e01a-5187-855f-441c69f9631e',1,null,null,'spoken & written','completely – used to emphasize what you are saying',null,null,'کاملاً، تماماً؛ حتماً (تأکید)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"It’s perfectly normal to be nervous before a performance.","translation":"عصبی بودن قبل از اجرا کاملاً طبیعی است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000350115.mp3"},{"sentence":"The sale was perfectly legal.","translation":"فروش کاملا قانونی بود","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001559908.mp3"},{"sentence":"You can get a perfectly good coat at Sears for a lot less money.","translation":"شما می توانید با پول بسیار کمتر یک کت کاملاً خوب در سیرز تهیه کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001559909.mp3"}]'::jsonb,3),
('2ee72557-1345-5e95-9a40-b689d1947061','1222304d-e01a-5187-855f-441c69f9631e',2,null,null,'spoken & written','in a perfect way',null,null,'به روشی کامل','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The plan worked perfectly.","translation":"طرح کاملاً جواب داد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000350111.mp3"},{"sentence":"The steaks were perfectly cooked.","translation":"استیک ها کاملا پخته شده بودند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001559910.mp3"}]'::jsonb,2),
('f8db189b-8e51-5aa1-94a5-dc0a72088d2e','7294d669-7952-5d1b-b98b-9c342c86d265',1,null,null,'spoken & written','continuing to exist for a long time or for all the time in the future',null,null,'دائمی، ماندگار؛ مستمر (استخدام)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He gave up a permanent job in order to freelance.","translation":"او شغل دائمی را رها کرد تا آزاد شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000351747.mp3"},{"sentence":"a permanent change in your eating habits","translation":"تغییر دائمی در عادات غذایی شما","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001560106.mp3"},{"sentence":"The blindness that the disease causes will be permanent.","translation":"نابینایی که این بیماری ایجاد می کند دائمی خواهد بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001560107.mp3"},{"sentence":"Miller soon became a permanent fixture (= someone or something that is always there ) on the team.","translation":"میلر به زودی به یک ثابت ثابت (= کسی یا چیزی که همیشه آنجاست) در تیم تبدیل شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001560108.mp3"}]'::jsonb,4),
