('b53de9ab-7d87-56b1-b462-599236c9ad0f','a1bf3f61-fbcd-5dee-8e40-e9b5808df1ac',1,null,null,'spoken & written','the people who work in a company, organization , or military force','[ plural ]',null,'کارکنان، کارمندان (سازمان)؛ پرسنل؛ افراد (ارتش)','{}'::text[],'{}'::text[],array['military/service personnel There have been attacks upon US military personnel.','security personnel Security personnel have become more thorough in checking passengers'' bags.','medical personnel There is an acute shortage of medical personnel.','technical personnel 800 technical personnel do the design and development of software.','trained/qualified personnel The unit is staffed by trained personnel.','skilled personnel Organizations need to be able to attract skilled personnel.','senior personnel It is crucial that senior personnel be on site from at least 8 am to 8 pm.','key personnel Many of the key personnel have left.']::text[],'[{"sentence":"senior military personnel","translation":"پرسنل ارشد نظامی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001766632.mp3"},{"sentence":"doctors and other medical personnel","translation":"پزشکان و سایر پرسنل پزشکی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001766633.mp3"},{"sentence":"All personnel are to receive security badges.","translation":"همه پرسنل باید نشان امنیتی دریافت کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000353532.mp3"}]'::jsonb,3),
('3ef44618-3e69-5b67-a4ad-4c8bb4309c93','a1bf3f61-fbcd-5dee-8e40-e9b5808df1ac',2,null,null,'spoken & written','the department in a company that chooses people for jobs and deals with their complaints , problems etc','[ uncountable ]',null,'بخشی در یک شرکت که افراد را برای شغل انتخاب می کند و به شکایات، مشکلات و غیره آنها رسیدگی می کند',array['human resources']::text[],'{}'::text[],array['military/service personnel There have been attacks upon US military personnel.','security personnel Security personnel have become more thorough in checking passengers'' bags.','medical personnel There is an acute shortage of medical personnel.','technical personnel 800 technical personnel do the design and development of software.','trained/qualified personnel The unit is staffed by trained personnel.','skilled personnel Organizations need to be able to attract skilled personnel.','senior personnel It is crucial that senior personnel be on site from at least 8 am to 8 pm.','key personnel Many of the key personnel have left.']::text[],'[{"sentence":"A copy should then be sent to Personnel for our files.","translation":"سپس باید یک نسخه برای فایل های ما به پرسنل ارسال شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001584612.mp3"},{"sentence":"the personnel department","translation":"بخش پرسنل","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001766634.mp3"}]'::jsonb,2),
('63cdb48e-4a33-5c02-8673-d79aa2918085','94c9894d-ad96-5324-82ff-c15b92b03299',1,null,null,'spoken & written','a photographic copy , especially of something printed , written, or drawn',null,null,'فتوکپی، کپی (سند)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I sent him the original document, not a photocopy.","translation":"اصل سند را برایش فرستادم نه فتوکپی.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000357314.mp3"}]'::jsonb,1),
('ff67d102-d09e-525b-88b5-d8960a820fa6','f694c5f3-793b-5a16-9cd9-86605ee03ca8',1,null,null,'spoken & written','to make a photographic copy of something',null,null,'فتوکپی کردن، کپی کردن (سند)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Leave the papers with me and I’ll get them photocopied.","translation":"برگه ها را نزد من بگذارید و من از آنها فتوکپی خواهم گرفت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000357324.mp3"}]'::jsonb,1),
