('92da2e7e-e274-53d4-aba4-892c1d9e75ff','e7ce3707-0a13-5026-bbce-8c632286b6f6',1,null,null,'spoken & written','relating to the government, politics , and public affairs of a country',null,null,'سیاسی، سیاسی‌کاری (مسائل)؛ سیاسی (جزئیات)','{}'::text[],'{}'::text[],array['a political party I am not a member of any political party.','a political system Our political system should give ordinary citizens more power.','a political leader a strong political leader','political power The poor have little political power.','political rights Every individual should have equal political rights.','somebody''s political career He is facing the biggest decision of his political career.','political life At that time women were excluded from the political life of the country.','a political issue Health care has become a major political issue.','a political solution They are eager for a political solution after years of war.']::text[],'[{"sentence":"Education is now a major political issue.","translation":"در حال حاضر آموزش و پرورش به یک موضوع مهم سیاسی تبدیل شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001574054.mp3"},{"sentence":"a time of political and social change","translation":"دوران تحولات سیاسی و اجتماعی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001574079.mp3"},{"sentence":"The U.S. has two main political parties.","translation":"ایالات متحده دو حزب سیاسی اصلی دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001574053.mp3"},{"sentence":"The UN is seeking a political solution rather than a military one.","translation":"سازمان ملل به جای راه حل نظامی به دنبال راه حل سیاسی است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001574070.mp3"},{"sentence":"political jokes","translation":"شوخی های سیاسی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001764416.mp3"},{"sentence":"the workers’ struggle for political power","translation":"مبارزه کارگران برای قدرت سیاسی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001574061.mp3"}]'::jsonb,6),
('873a0418-83b0-5b29-a4af-ba11b45e317a','e7ce3707-0a13-5026-bbce-8c632286b6f6',2,null,null,'spoken & written','relating to the ways that different people have power within a group, organization etc',null,null,'مربوط به راه هایی است که افراد مختلف در یک گروه، سازمان و غیره قدرت دارند','{}'::text[],'{}'::text[],array['a political party I am not a member of any political party.','a political system Our political system should give ordinary citizens more power.','a political leader a strong political leader','political power The poor have little political power.','political rights Every individual should have equal political rights.','somebody''s political career He is facing the biggest decision of his political career.','political life At that time women were excluded from the political life of the country.','a political issue Health care has become a major political issue.','a political solution They are eager for a political solution after years of war.']::text[],'[{"sentence":"a purely political decision","translation":"یک تصمیم کاملا سیاسی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001574081.mp3"},{"sentence":"The appointment was given to Wellington, mainly for political reasons.","translation":"این انتصاب عمدتاً به دلایل سیاسی به ولینگتون داده شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001574085.mp3"}]'::jsonb,2),
('6475682b-786b-5755-b556-728c872584c0','e7ce3707-0a13-5026-bbce-8c632286b6f6',3,null,null,'spoken & written','interested in or active in politics','[ not before noun ]',null,'علاقه مند یا فعال در سیاست','{}'::text[],'{}'::text[],array['a political party I am not a member of any political party.','a political system Our political system should give ordinary citizens more power.','a political leader a strong political leader','political power The poor have little political power.','political rights Every individual should have equal political rights.','somebody''s political career He is facing the biggest decision of his political career.','political life At that time women were excluded from the political life of the country.','a political issue Health care has become a major political issue.','a political solution They are eager for a political solution after years of war.']::text[],'[{"sentence":"Most students aren’t very political.","translation":"اکثر دانشجویان خیلی سیاسی نیستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000345809.mp3"}]'::jsonb,1),
('d348bbc2-0e57-5b76-81d8-0ceb468356e7','e7ce3707-0a13-5026-bbce-8c632286b6f6',4,null,null,'spoken & written',null,null,'political football','سیاسی، سیاسی‌کاری (مسائل)؛ سیاسی (جزئیات)','{}'::text[],'{}'::text[],array['a political party I am not a member of any political party.','a political system Our political system should give ordinary citizens more power.','a political leader a strong political leader','political power The poor have little political power.','political rights Every individual should have equal political rights.','somebody''s political career He is facing the biggest decision of his political career.','political life At that time women were excluded from the political life of the country.','a political issue Health care has become a major political issue.','a political solution They are eager for a political solution after years of war.']::text[],'[]'::jsonb,0),
('7dfcec87-06d6-58e0-b37d-9606abcdd611','521e4ef4-69b2-5cdb-9b6e-8f7a88c22cf7',1,null,null,'spoken & written','the process of making air , water, soil etc dangerously dirty and not suitable for people to use, or the state of being dangerously dirty',null,null,'آلودگی، آلایندگی؛ آلاینده (هوا)؛ آلوده (سطح)','{}'::text[],'{}'::text[],array['bad/serious/severe The mines have caused serious pollution of the river system. The pollution was so bad that most of the fish died.','air pollution Air pollution can cause breathing problems for some people.','atmospheric pollution formal (= air pollution ) The oil wells continued to burn, causing atmospheric pollution on a massive scale.','water/river pollution The National Rivers Authority tests levels of water pollution.','marine pollution formal (= pollution of the sea ) Oil spills are a major cause of marine pollution.','environmental pollution Most environmental pollution originates in the developed countries.','industrial pollution (= from factories ) A study has linked ill health in the area with industrial pollution.','chemical pollution Chemical pollution threatens the survival of these animals.','reduce/cut pollution New measures are needed to reduce pollution from cars.','control pollution The water company is failing to control pollution.','tackle/combat pollution (= try to deal with it ) Governments must tackle pollution now.','prevent pollution Efforts are being made to prevent further pollution.','monitor pollution (= measure it ) It is possible to monitor pollution from incinerator chimneys.','pollution levels The aim is to reduce pollution levels to those of the 1930s.','a pollution problem Environmentalists fear that the new factories will lead to severe pollution problems.','pollution control Effective pollution control was not being undertaken.','a source/cause of pollution The factory was a clear source of pollution. Fumes from cars are a major cause of air pollution.']::text[],'[{"sentence":"California’s tough anti-pollution laws","translation":"قوانین سختگیرانه ضد آلودگی کالیفرنیا","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000306951.mp3"},{"sentence":"air pollution from traffic fumes","translation":"آلودگی هوا ناشی از دودهای ترافیکی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001574240.mp3"},{"sentence":"The costs of pollution control must be considered.","translation":"هزینه های کنترل آلودگی باید در نظر گرفته شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001574243.mp3"}]'::jsonb,3),
('8879da46-6644-559f-b176-65f1d8bf4b9e','521e4ef4-69b2-5cdb-9b6e-8f7a88c22cf7',2,null,null,'spoken & written','substances that make air, water, soil etc dangerously dirty',null,null,'موادی که هوا، آب، خاک و غیره را به طور خطرناکی کثیف می کند','{}'::text[],'{}'::text[],array['bad/serious/severe The mines have caused serious pollution of the river system. The pollution was so bad that most of the fish died.','air pollution Air pollution can cause breathing problems for some people.','atmospheric pollution formal (= air pollution ) The oil wells continued to burn, causing atmospheric pollution on a massive scale.','water/river pollution The National Rivers Authority tests levels of water pollution.','marine pollution formal (= pollution of the sea ) Oil spills are a major cause of marine pollution.','environmental pollution Most environmental pollution originates in the developed countries.','industrial pollution (= from factories ) A study has linked ill health in the area with industrial pollution.','chemical pollution Chemical pollution threatens the survival of these animals.','reduce/cut pollution New measures are needed to reduce pollution from cars.','control pollution The water company is failing to control pollution.','tackle/combat pollution (= try to deal with it ) Governments must tackle pollution now.','prevent pollution Efforts are being made to prevent further pollution.','monitor pollution (= measure it ) It is possible to monitor pollution from incinerator chimneys.','pollution levels The aim is to reduce pollution levels to those of the 1930s.','a pollution problem Environmentalists fear that the new factories will lead to severe pollution problems.','pollution control Effective pollution control was not being undertaken.','a source/cause of pollution The factory was a clear source of pollution. Fumes from cars are a major cause of air pollution.']::text[],'[{"sentence":"a plan to reduce pollution","translation":"طرحی برای کاهش آلودگی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001574244.mp3"},{"sentence":"the effects of industrial pollution on the population","translation":"اثرات آلودگی صنعتی بر جمعیت","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001764381.mp3"},{"sentence":"The chemicals have been identified as a source of pollution .","translation":"مواد شیمیایی به عنوان منبع آلودگی شناسایی شده اند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001574250.mp3"}]'::jsonb,3),
('8230eb59-13ed-52fc-912e-a190d96fc9bb','0446e292-9a23-5436-9e64-a891a8394c9b',1,null,null,'spoken & written','likely to develop into a particular type of person or thing in the future',null,null,'بالقوه، احتمالی (فرد)',array['possible']::text[],'{}'::text[],array['a potential customer/buyer/client Advertisers want to reach as many potential customers as possible.','a potential candidate Party leaders have put together a list of 10 potential candidates.','a potential problem There is a potential problem with the new equipment.','a potential danger/threat/risk Tired drivers are a potential danger to other road users.','potential conflict Funding is an area of potential conflict between the two departments.','a potential benefit The potential benefits must be weighed up against the costs involved.','a potential source of something A dirty kitchen is a potential source of infection.']::text[],'[{"sentence":"new ways of attracting potential customers","translation":"روش های جدید جذب مشتریان بالقوه","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001665167.mp3"},{"sentence":"the potential benefits of the new system","translation":"مزایای بالقوه سیستم جدید","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001665170.mp3"},{"sentence":"the potential risks to health associated with the drug","translation":"خطرات بالقوه برای سلامتی مرتبط با دارو","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001665173.mp3"}]'::jsonb,3),
('c4a320f0-b52d-59e2-bd05-e856b1714e75','d43f43a6-b1b5-5cf4-b150-006e6abc8d60',1,null,null,'spoken & written','the possibility that something will develop in a particular way, or have a particular effect',null,null,'استعداد، قابلیت (رشد)؛ پتانسیل (بازار)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The company certainly has the potential for growth.","translation":"این شرکت قطعا پتانسیل رشد را دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001665175.mp3"},{"sentence":"the potential of the Internet to create jobs","translation":"پتانسیل اینترنت برای ایجاد شغل","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001665179.mp3"}]'::jsonb,2),
('f565611f-63a1-5891-aca4-681d3eb98024','d43f43a6-b1b5-5cf4-b150-006e6abc8d60',2,null,null,'spoken & written','if people or things have potential, they have a natural ability or quality that could develop to make them very good',null,null,'اگر افراد یا چیزها پتانسیل بالقوه ای داشته باشند، توانایی یا کیفیت طبیعی دارند که می تواند آنها را بسیار خوب کند','{}'::text[],'{}'::text[],array['have potential When he saw I had some potential, he gave me extra coaching.','show potential Nicholson soon showed great potential as an actor.','develop your potential (= succeed by using your skills or talents ) A good school aims to enable pupils to develop their potential.','achieve/fulfil/reach/realize your potential (= succeed as much as you have the potential to succeed ) A lot of athletes find it difficult to achieve their potential.','exploit somebody’s/something’s potential (= use all the qualities that someone or something has ) Until now, the island has not exploited its potential as a tourist destination.','unlock/unleash somebody’s potential (= allow them to succeed as well as they can ) Training is a way of unlocking the potential of the workforce.','great/enormous/considerable potential This is a team with great potential.','somebody’s full potential We continuously seek to develop people to their full potential.','somebody’s true potential (= their full potential ) Malaysia only showed glimpses of their true potential in the final stages of the tournament.','commercial/economic potential (= the potential to earn money ) They were quick to recognize the band’s commercial potential.','leadership potential (= the potential to become a leader ) She always felt that I had leadership potential.','star potential (= the potential to be a star in music, films etc ) The woman who spotted Kate’s star potential was Sarah Doukas.','human potential (= people’s abilities or qualities ) Mass unemployment is a shameful waste of human potential.']::text[],'[{"sentence":"She has the potential to become a champion.","translation":"او پتانسیل قهرمان شدن را دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001665181.mp3"},{"sentence":"a young player with great potential","translation":"بازیکنی جوان با پتانسیل بالا","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000314387.mp3"}]'::jsonb,2),
('b2fee01a-4d55-5969-80d6-946008be6794','d43f43a6-b1b5-5cf4-b150-006e6abc8d60',3,null,null,'technical','the difference in voltage between two points on an electrical circuit',null,null,'تفاوت ولتاژ بین دو نقطه در مدار الکتریکی','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('b6ffd4f5-2681-56c1-8c10-5564ebd7c793','2f466ff1-fd4f-5206-9184-c09ad48efa18',1,'real','واقعی','spoken & written','relating to real situations and events rather than ideas, emotions etc',null,null,'عملی، کاربردی؛ واقع‌گرا (نظر)؛ مقتصد (حالت)','{}'::text[],'{}'::text[],array['practical experience You have to gain practical experience before you qualify as a solicitor.','practical work Archaeology students are required to do a certain amount of practical work.','practical problems/difficulties The local Social Services Department may be able to help with practical problems.','practical help/support ( also practical assistance formal ) There will be trained people available to listen and to provide practical help.','practical advice The booklets offer clear, practical advice on running your business.','practical use Knowledge without understanding is of little practical use.','practical considerations There are a number of practical considerations that must be taken into account when choosing a car.','practical implications He was well aware of the practical implications of his theory.','in practical terms In practical terms, the experiment is going to be difficult.']::text[],'[{"sentence":"Candidates should have training and practical experience in basic electronics.","translation":"داوطلبان باید آموزش و تجربه عملی در زمینه الکترونیک اولیه داشته باشند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000317330.mp3"},{"sentence":"the practical problems of old age","translation":"مشکلات عملی سالمندی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000317331.mp3"},{"sentence":"They provide financial and practical help for disabled students.","translation":"آنها به دانش آموزان معلول کمک مالی و عملی می کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001567964.mp3"},{"sentence":"a combination of theoretical and practical training","translation":"ترکیبی از آموزش نظری و عملی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001567968.mp3"},{"sentence":"They haven’t thought about the practical consequences of the new regulations.","translation":"آنها به عواقب عملی مقررات جدید فکر نکرده اند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001567969.mp3"},{"sentence":"In practical terms , this means spending more time with each student.","translation":"از نظر عملی، این به معنای صرف زمان بیشتر با هر دانش آموز است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001567970.mp3"}]'::jsonb,6),
('19939590-c020-55ab-93d0-9a0527ef1d3f','2f466ff1-fd4f-5206-9184-c09ad48efa18',2,'effective','موثر','spoken & written','practical plans, methods etc are likely to succeed or be effective in a situation',null,null,'برنامه های عملی، روش ها و غیره احتمالاً در یک موقعیت موفق یا مؤثر هستند','{}'::text[],'{}'::text[],array['practical experience You have to gain practical experience before you qualify as a solicitor.','practical work Archaeology students are required to do a certain amount of practical work.','practical problems/difficulties The local Social Services Department may be able to help with practical problems.','practical help/support ( also practical assistance formal ) There will be trained people available to listen and to provide practical help.','practical advice The booklets offer clear, practical advice on running your business.','practical use Knowledge without understanding is of little practical use.','practical considerations There are a number of practical considerations that must be taken into account when choosing a car.','practical implications He was well aware of the practical implications of his theory.','in practical terms In practical terms, the experiment is going to be difficult.']::text[],'[{"sentence":"It doesn’t sound like a very practical solution.","translation":"راه حل چندان عملی به نظر نمی رسد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000317351.mp3"},{"sentence":"a practical way of achieving greater efficiency","translation":"یک راه عملی برای دستیابی به کارایی بیشتر","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001567974.mp3"},{"sentence":"Unfortunately, there’s no practical alternative to driving.","translation":"متأسفانه، هیچ جایگزین عملی برای رانندگی وجود ندارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001567978.mp3"},{"sentence":"a practical guide to buying and selling a house","translation":"راهنمای عملی خرید و فروش خانه","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001567982.mp3"}]'::jsonb,4),
('7568507f-22e6-5ae9-a964-1c06fc31b976','2f466ff1-fd4f-5206-9184-c09ad48efa18',3,'clear thinking','تفکر روشن','spoken & written','a practical person is good at dealing with problems and making decisions based on what is possible and what will really work',null,null,'یک فرد عملی در برخورد با مشکلات و تصمیم گیری بر اساس آنچه ممکن است و واقعاً کارساز است، خوب است','{}'::text[],'{}'::text[],array['practical experience You have to gain practical experience before you qualify as a solicitor.','practical work Archaeology students are required to do a certain amount of practical work.','practical problems/difficulties The local Social Services Department may be able to help with practical problems.','practical help/support ( also practical assistance formal ) There will be trained people available to listen and to provide practical help.','practical advice The booklets offer clear, practical advice on running your business.','practical use Knowledge without understanding is of little practical use.','practical considerations There are a number of practical considerations that must be taken into account when choosing a car.','practical implications He was well aware of the practical implications of his theory.','in practical terms In practical terms, the experiment is going to be difficult.']::text[],'[{"sentence":"She’s a very practical person .","translation":"او یک فرد بسیار عملی است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000317341.mp3"},{"sentence":"I was very shocked, but tried to be practical and think what to do.","translation":"من خیلی شوکه شده بودم، اما سعی کردم عملی باشم و فکر کنم چه کار کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001567987.mp3"}]'::jsonb,2),
('73ffbe90-48d5-5c18-a3d2-0a45e47ce1e3','2f466ff1-fd4f-5206-9184-c09ad48efa18',4,'suitable','مناسب','spoken & written','useful or suitable for a particular purpose or situation',null,null,'مفید یا مناسب برای یک هدف یا موقعیت خاص','{}'::text[],'{}'::text[],array['practical experience You have to gain practical experience before you qualify as a solicitor.','practical work Archaeology students are required to do a certain amount of practical work.','practical problems/difficulties The local Social Services Department may be able to help with practical problems.','practical help/support ( also practical assistance formal ) There will be trained people available to listen and to provide practical help.','practical advice The booklets offer clear, practical advice on running your business.','practical use Knowledge without understanding is of little practical use.','practical considerations There are a number of practical considerations that must be taken into account when choosing a car.','practical implications He was well aware of the practical implications of his theory.','in practical terms In practical terms, the experiment is going to be difficult.']::text[],'[{"sentence":"Skirts aren’t very practical in my kind of work.","translation":"دامن در نوع کار من خیلی کاربردی نیست.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000317370.mp3"}]'::jsonb,1),
('f9921683-319b-5b70-ac4f-a1ddfd1b287c','2f466ff1-fd4f-5206-9184-c09ad48efa18',5,'using your hands','با استفاده از دستان خود','spoken & written','good at repairing or making things',null,null,'در تعمیر یا ساخت چیزها خوب است','{}'::text[],'{}'::text[],array['practical experience You have to gain practical experience before you qualify as a solicitor.','practical work Archaeology students are required to do a certain amount of practical work.','practical problems/difficulties The local Social Services Department may be able to help with practical problems.','practical help/support ( also practical assistance formal ) There will be trained people available to listen and to provide practical help.','practical advice The booklets offer clear, practical advice on running your business.','practical use Knowledge without understanding is of little practical use.','practical considerations There are a number of practical considerations that must be taken into account when choosing a car.','practical implications He was well aware of the practical implications of his theory.','in practical terms In practical terms, the experiment is going to be difficult.']::text[],'[{"sentence":"I’m not very practical – I can’t even change a light bulb.","translation":"من خیلی اهل عمل نیستم - حتی نمی توانم یک لامپ را عوض کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000317381.mp3"}]'::jsonb,1),
('845084a8-00fe-525e-8e43-6d74d92855c0','2f466ff1-fd4f-5206-9184-c09ad48efa18',6,null,null,'spoken & written',null,null,'for/to all practical purposes','عملی، کاربردی؛ واقع‌گرا (نظر)؛ مقتصد (حالت)','{}'::text[],'{}'::text[],array['practical experience You have to gain practical experience before you qualify as a solicitor.','practical work Archaeology students are required to do a certain amount of practical work.','practical problems/difficulties The local Social Services Department may be able to help with practical problems.','practical help/support ( also practical assistance formal ) There will be trained people available to listen and to provide practical help.','practical advice The booklets offer clear, practical advice on running your business.','practical use Knowledge without understanding is of little practical use.','practical considerations There are a number of practical considerations that must be taken into account when choosing a car.','practical implications He was well aware of the practical implications of his theory.','in practical terms In practical terms, the experiment is going to be difficult.']::text[],'[]'::jsonb,0),
('941aca41-ad41-5c9f-b392-61c4dc4afdf3','2f466ff1-fd4f-5206-9184-c09ad48efa18',7,null,null,'spoken & written',null,null,'practical certainty/disaster/sell-out etc','عملی، کاربردی؛ واقع‌گرا (نظر)؛ مقتصد (حالت)','{}'::text[],'{}'::text[],array['practical experience You have to gain practical experience before you qualify as a solicitor.','practical work Archaeology students are required to do a certain amount of practical work.','practical problems/difficulties The local Social Services Department may be able to help with practical problems.','practical help/support ( also practical assistance formal ) There will be trained people available to listen and to provide practical help.','practical advice The booklets offer clear, practical advice on running your business.','practical use Knowledge without understanding is of little practical use.','practical considerations There are a number of practical considerations that must be taken into account when choosing a car.','practical implications He was well aware of the practical implications of his theory.','in practical terms In practical terms, the experiment is going to be difficult.']::text[],'[]'::jsonb,0),
('c6fc3592-85d6-5530-85e2-23dac0bf9a9d','4fb5d4bd-daf5-5778-a1b4-b7b0878ed96c',1,null,null,'spoken & written','a lesson or examination in science , cooking etc in which you have to do or make something yourself rather than write or read about it',null,null,'یک درس یا امتحان در علوم، آشپزی و غیره که در آن شما باید چیزی را خودتان انجام دهید یا بسازید به جای نوشتن یا خواندن در مورد آن','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a chemistry practical","translation":"شیمی عملی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000317408.mp3"}]'::jsonb,1),
('492b8f13-1cb5-581c-81fe-318d9febd055','9e8e26c1-7d15-574b-bcfe-5beea650bb65',1,null,null,'spoken & written','exactly and correctly',null,null,'دقیقاً، درست؛ همینطور (تأکید)',array['exactly']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Temperature can be measured precisely.","translation":"دما را می توان به طور دقیق اندازه گیری کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001568152.mp3"},{"sentence":"He arrived at precisely four o''clock.","translation":"دقیقا ساعت چهار رسید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa020180.mp3"},{"sentence":"It is difficult to know precisely how much impact the changes will have.","translation":"دشوار است که دقیقاً بدانیم تغییرات چقدر تأثیر خواهند داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001568155.mp3"},{"sentence":"What, precisely, does that mean?","translation":"این دقیقاً به چه معناست؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000320134.mp3"},{"sentence":"Lathes make wheels, or, more precisely , they make cylindrical objects.","translation":"ماشین های تراش چرخ یا به عبارت دقیق تر، اشیاء استوانه ای می سازند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001568156.mp3"}]'::jsonb,5),
('7233240e-9128-5900-af44-26fc14eea48a','9e8e26c1-7d15-574b-bcfe-5beea650bb65',2,null,null,'spoken & written','used to emphasize that a particular thing is completely true or correct',null,null,'برای تأکید بر اینکه یک چیز خاص کاملاً درست یا صحیح است استفاده می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Women in these jobs are paid less precisely because most of the jobs are held by women rather than men.","translation":"زنان در این مشاغل دقیقاً دستمزد کمتری می گیرند زیرا بیشتر مشاغل در اختیار زنان است تا مردان.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000320139.mp3"},{"sentence":"She’s precisely the kind of person we’re looking for.","translation":"او دقیقاً همان کسی است که ما به دنبالش هستیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000320140.mp3"}]'::jsonb,2),
('9b70cab1-965b-5bf5-862e-d6977a8188e1','9e8e26c1-7d15-574b-bcfe-5beea650bb65',3,null,null,'spoken','used to say that you agree completely with someone',null,null,'میگفت تو کاملا با کسی موافقی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"‘It needs to be dealt with now.’ ‘Precisely, before it gets any worse.’","translation":"\"الان باید با آن برخورد شود.\" \"دقیقاً، قبل از اینکه بدتر شود.\"","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000320145.mp3"}]'::jsonb,1),
