('3a60b0ae-b8d3-5fd7-b3f0-02ff6fb1d6e9','d7b6f415-4745-580e-b863-c62d84eee970',3,'business','کسب و کار','spoken & written','the main person in a business or organization , who can make important business decisions and is legally responsible for them','[ countable ]',null,'شخص اصلی در یک کسب و کار یا سازمان که می تواند تصمیمات تجاری مهمی را اتخاذ کند و قانوناً در قبال آنها مسئولیت دارد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The principal of the business has an office in New York.","translation":"مدیر این کسب و کار دفتری در نیویورک دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001698660.mp3"}]'::jsonb,1),
('33c041cd-5a4b-5bec-8ac9-5bb923f5e2e0','d7b6f415-4745-580e-b863-c62d84eee970',4,'performer','مجری','spoken & written','the main performer in a play or in a group of musicians , dancers etc','[ countable ]',null,'نوازنده اصلی در یک نمایش یا در گروهی از نوازندگان، رقصندگان و غیره','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She later became a principal with the Royal Ballet.","translation":"او بعداً به عنوان مدیر باله سلطنتی انتخاب شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001698662.mp3"}]'::jsonb,1),
