('e19482d2-ffd1-5bc1-ab93-ab285bc5096f','bf3e5fab-02d7-5c60-ab08-661b7576d41c',3,null,null,'spoken & written','evenly arranged or shaped',null,null,'به طور مساوی چیده شده یا شکل گرفته است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The plants are regularly spaced.","translation":"گیاهان به طور منظم با هم فاصله دارند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001652443.mp3"},{"sentence":"regularly shaped crystals","translation":"کریستال هایی با شکل منظم","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001652444.mp3"}]'::jsonb,2),
('c2198a5c-4d47-5bd1-9c4c-24fadb8ca3c7','0b4273b3-cb21-5df8-a74e-6c71a0a60dd9',1,null,null,'spoken & written','to give support to an opinion , idea, or feeling, and make it stronger',null,null,'تقویت کردن، محکم کردن (عقیده)؛ ستون‌بندی کردن (ساختمان)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The film reinforces the idea that women should be pretty and dumb.","translation":"این فیلم این ایده را تقویت می کند که زنان باید زیبا و گنگ باشند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001652545.mp3"}]'::jsonb,1),
