('359ec396-87b7-5b3f-80b9-4f313f6957b4','e8d4725c-f809-5e83-936c-88b52d5bee3f',2,null,null,'spoken & written','believing strongly in your religion and obeying its rules carefully',null,null,'اعتقاد راسخ به دین خود و رعایت دقیق احکام آن','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a deeply religious person","translation":"یک فرد عمیقا مذهبی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000772445.mp3"}]'::jsonb,1),
('d9be1389-75ce-5086-a9e2-d0e6ecdeeaa4','66fd03e0-aa73-55be-bf84-12fbe3ef2f3c',1,null,null,'spoken & written','the remaining people or things are those that are left when the others have gone, been used, or been dealt with',null,null,'باقی‌مانده، باقی (چیزها)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The few remaining guests were in the kitchen.","translation":"چند مهمان باقی مانده در آشپزخانه بودند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000772722.mp3"},{"sentence":"Add the remaining ingredients and simmer for 30 minutes.","translation":"بقیه مواد را اضافه کنید و 30 دقیقه بجوشانید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-002025286.mp3"},{"sentence":"The only remaining question is whether we can raise the money.","translation":"تنها سوال باقی مانده این است که آیا ما می توانیم پول را جمع آوری کنیم؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000772723.mp3"}]'::jsonb,3),
('32832cbf-6958-5241-abdd-cc38cd8f0c9d','a54cf380-2028-5d32-840c-901a117c1ed2',1,'speak for somebody','برای کسی صحبت کن','spoken & written','to officially speak or take action for another person or group of people','[ transitive ]',null,'نمایندگی کردن؛ به‌نمایندگی از (کسی)؛ معادل بودن (نماد)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Mr Kobayashi was chosen to represent the company at the conference.","translation":"آقای کوبایاشی به عنوان نماینده شرکت در کنفرانس انتخاب شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000776836.mp3"}]'::jsonb,1),
('077bf4ed-3e27-57b1-98dc-509a5e459062','a54cf380-2028-5d32-840c-901a117c1ed2',2,'in court','در دادگاه','spoken & written','to speak officially for someone in a court of law','[ transitive ]',null,'صحبت رسمی برای کسی در دادگاه قانون','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She decided to represent herself (= speak for herself without a lawyer ) during the trial.","translation":"او تصمیم گرفت در طول دادگاه وکالت خود را (= بدون وکیل برای خودش صحبت کند).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001770945.mp3"}]'::jsonb,1),
('f09d5823-06ca-5b39-899f-bb1a6ee2b318','a54cf380-2028-5d32-840c-901a117c1ed2',3,'be something','چیزی باشد','spoken & written','to form or be something','[ linking verb ]',null,'شکل دادن یا چیزی بودن','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"European orders represented 30 percent of our sales last year.","translation":"سفارشات اروپایی 30 درصد از فروش ما را در سال گذشته تشکیل می دادند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001607415.mp3"},{"sentence":"This treatment represents a significant advance in the field of cancer research.","translation":"این درمان نشان دهنده پیشرفت قابل توجهی در زمینه تحقیقات سرطان است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001607410.mp3"}]'::jsonb,2),
