('a8075e71-4741-5459-8b95-2f318e2981ec','a881e7af-f8bb-5508-9f50-e0c7f65f61e4',2,'easily offended','به راحتی توهین می شود','spoken & written','easily upset or offended by events or things that people say',null,'hypersensitive','به راحتی از رویدادها یا چیزهایی که مردم می گویند ناراحت یا آزرده می شوند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a very sensitive child","translation":"یک کودک بسیار حساس","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000700929.mp3"},{"sentence":"Laura’s sensitive about her weight.","translation":"لورا به وزن خود حساس است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000700932.mp3"},{"sentence":"Throughout her career she remained very sensitive to criticism.","translation":"او در طول زندگی حرفه ای خود به انتقاد بسیار حساس بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001635298.mp3"}]'::jsonb,3),
