('8d1b6a0c-6f34-5244-b424-f40006edd60d','a881e7af-f8bb-5508-9f50-e0c7f65f61e4',4,'situation/subject','موقعیت/موضوع','spoken & written','a situation or subject that is sensitive needs to be dealt with very carefully, because it is secret or because it may offend people',null,null,'موقعیت یا موضوعی که حساس است باید بسیار با دقت برخورد شود، زیرا مخفی است یا ممکن است باعث آزار مردم شود.','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Abortion is a very sensitive issue.","translation":"سقط جنین یک موضوع بسیار حساس است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000700958.mp3"},{"sentence":"sensitive matters such as national security","translation":"مسائل حساسی مانند امنیت ملی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001635304.mp3"},{"sentence":"highly sensitive information","translation":"اطلاعات بسیار حساس","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001777422.mp3"}]'::jsonb,3),
