('ae021185-c53b-58ff-b56e-292522e0dcf6','a7a8cba9-199b-5207-86ea-fb8dbf1ba06c',1,null,null,'spoken & written','in or to a place, but you do not say or know exactly where',null,null,'جایی، جا (ناشناس)؛ کجا (ناشناخته)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"My wallet must be around here somewhere.","translation":"کیف پول من باید یک جایی اینجا باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001633789.mp3"},{"sentence":"There must be somewhere to eat cheaply in this town.","translation":"باید جایی برای غذا خوردن ارزان در این شهر وجود داشته باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000648814.mp3"},{"sentence":"Is there somewhere safe where I can leave my bike?","translation":"آیا جایی امن وجود دارد که بتوانم دوچرخه ام را بگذارم؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000648817.mp3"},{"sentence":"Go and play somewhere else (= in a different place ) – I’m trying to work.","translation":"برو و جای دیگری بازی کن (= در جای دیگری) - من سعی می کنم کار کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001633790.mp3"},{"sentence":"We could meet for dinner at Giorgio’s or somewhere (= or a similar place ) .","translation":"می‌توانیم برای شام در جورجیو یا جایی (= یا یک مکان مشابه) ملاقات کنیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001633795.mp3"}]'::jsonb,5),
