('e5759e8a-1b89-51fd-9c77-6477fb0db293','c0e8a310-004c-5c7c-9ae9-92ed1e221deb',1,null,null,'spoken & written','relating to your spirit rather than to your body or mind',null,null,'روحانی، معنوی؛ روحانی (فرد)؛ روحانی (جسد)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Painting helps fill a spiritual need for beauty.","translation":"نقاشی به رفع نیاز معنوی به زیبایی کمک می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001668729.mp3"},{"sentence":"spiritual values","translation":"ارزش های معنوی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000659784.mp3"}]'::jsonb,2),
('a768a566-b742-53d0-9691-721a5f8dc4e6','c0e8a310-004c-5c7c-9ae9-92ed1e221deb',2,null,null,'spoken & written','relating to religion',null,null,'مربوط به دین',array['religious']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Islam was inspired by the teachings of the spiritual leader Mohammed.","translation":"اسلام از آموزه های رهبر معنوی محمد الهام گرفته شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001668730.mp3"}]'::jsonb,1),
