('e66687cc-32b6-5183-a209-db7d208fd643','09e6ded6-be17-5686-8267-8b6bf5e37b29',1,null,null,'spoken & written','done as part of a plan, especially in a military , business, or political situation',null,null,'راهبردی، استراتژیک؛ ساختگی (شراکت)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"UN forces made a strategic withdrawal.","translation":"نیروهای سازمان ملل یک عقب نشینی استراتژیک انجام دادند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000619527.mp3"},{"sentence":"strategic planning meetings","translation":"جلسات برنامه ریزی استراتژیک","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001600063.mp3"},{"sentence":"a strategic decision to move production to Hungary","translation":"یک تصمیم استراتژیک برای انتقال تولید به مجارستان","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001600067.mp3"}]'::jsonb,3),
