('36a14a0b-e909-5de6-818a-c0449f434ddd','f7fa49cc-0333-59ec-afd6-bab906b76e12',4,'change forms','تغییر فرم ها','spoken & written','to change something, or be changed, from one form into another','[ intransitive, transitive ]',null,'چیزی را تغییر دادن یا از شکلی به شکلی دیگر تغییر داد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"the danger of translating your emotions into actions","translation":"خطر تبدیل احساسات به اعمال","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000554374.mp3"},{"sentence":"Jokes often don’t translate well into print.","translation":"جوک ها اغلب به خوبی به صورت چاپی ترجمه نمی شوند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001613674.mp3"}]'::jsonb,2),
