('c1c55ce2-2d29-5fca-bb2e-058ba8dc3e39','cf8d9fda-727a-5c7f-b81a-8832bfab317f',2,null,null,'spoken & written','used to emphasize that the way you describe something is completely true','[ +adj/adverb ]',null,'برای تأکید بر این که روشی که شما چیزی را توصیف می کنید کاملاً درست است استفاده می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"In Canada, the situation is altogether different.","translation":"در کانادا، وضعیت کاملاً متفاوت است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001630728.mp3"},{"sentence":"This latest problem is altogether more serious.","translation":"این مشکل اخیر در کل جدی تر است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001630729.mp3"},{"sentence":"I wasn’t altogether happy about Mike staying over.","translation":"من اصلا از ماندن مایک خوشحال نبودم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001630736.mp3"},{"sentence":"The results were not altogether surprising.","translation":"نتایج در کل تعجب آور نبود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001837552.mp3"}]'::jsonb,4),
('aba20a66-732b-5dd2-beec-151b57b6675a','cf8d9fda-727a-5c7f-b81a-8832bfab317f',3,null,null,'spoken & written','used to show that you are referring to the total amount',null,null,'برای نشان دادن اینکه شما به کل مبلغ اشاره می کنید استفاده می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"There were five people altogether.","translation":"کلا پنج نفر بودند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000937992.mp3"},{"sentence":"How much do I owe you altogether?","translation":"در کل چقدر به شما بدهکارم؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000937993.mp3"}]'::jsonb,2),
('829d1f50-aeca-5960-aafa-617b3b76cc4c','cf8d9fda-727a-5c7f-b81a-8832bfab317f',4,null,null,'spoken & written','used to make a final statement about several things you have just mentioned',null,null,'برای اظهار نظر نهایی در مورد چندین موردی که به تازگی اشاره کردید استفاده می شود',array['all in all']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Lots of sunshine, wonderful food, and amazing nightlife – altogether a great vacation!","translation":"آفتاب زیاد، غذاهای فوق‌العاده، و زندگی شبانه شگفت‌انگیز - در مجموع یک تعطیلات عالی!","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001837553.mp3"}]'::jsonb,1),
