('05fe2387-ed60-566f-8a0e-47d8254892e2','d07d0a09-ffd2-5c6b-9df9-9a535f7810cc',6,null,null,'spoken & written',null,null,'for appearances’ sake/for the sake of appearances','ظاهر، شکل و شمایل؛ آمدن به انظار','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('c7372d39-8d12-54f7-b4c7-9bec205f6fbf','d07d0a09-ffd2-5c6b-9df9-9a535f7810cc',7,null,null,'spoken & written',null,null,'put in an appearance/make an appearance','ظاهر، شکل و شمایل؛ آمدن به انظار','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('ce3faea9-179c-5687-80b0-45a53ab9161c','d07d0a09-ffd2-5c6b-9df9-9a535f7810cc',8,'at a law court/meeting','در دادگاه/جلسه حقوقی','spoken & written','an occasion when someone goes to a court of law or official meeting to give information, answer questions etc','[ countable ]',null,'موقعیتی که شخصی برای ارائه اطلاعات، پاسخ به سؤالات و غیره به دادگاه حقوقی یا جلسه رسمی می رود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He is due to make another court appearance on Monday.","translation":"او قرار است روز دوشنبه بار دیگر در دادگاه حاضر شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001672331.mp3"}]'::jsonb,1),
('27a01292-3943-52e6-ab70-ca23f999c240','7dacac78-934d-57c1-a53f-d5ebbcef4ae8',1,null,null,'spoken & written','to understand how serious or important a situation or problem is or what someone’s feelings are','[ transitive ]',null,'قدردانی کردن؛ دریافتن (اهمیت چیزی)',array['realize']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He did not fully appreciate the significance of signing the contract.","translation":"او اهمیت امضای قرارداد را به طور کامل درک نکرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001672065.mp3"},{"sentence":"We appreciate that caring for children is an important job.","translation":"ما قدردانی می کنیم که مراقبت از کودکان یک شغل مهم است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001672068.mp3"},{"sentence":"It is difficult to appreciate how bad the situation had become.","translation":"درک این که وضعیت چقدر بد شده است دشوار است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001672071.mp3"}]'::jsonb,3),
('73c81924-6633-5d71-b348-7818963686c8','7dacac78-934d-57c1-a53f-d5ebbcef4ae8',2,null,null,'spoken & written','used to thank someone in a polite way or to say that you are grateful for something they have done','[ transitive ]',null,'از کسی به روشی مؤدبانه تشکر می کرد یا می گفت که برای کاری که انجام داده است سپاسگزار هستید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Thanks ever so much for your help, I really appreciate it.","translation":"همیشه از کمک شما بسیار سپاسگزارم، من واقعاً از آن سپاسگزارم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001672072.mp3"},{"sentence":"I appreciate your concern , but honestly, I’m fine.","translation":"من از نگرانی شما قدردانی می کنم، اما صادقانه بگویم، حالم خوب است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001672073.mp3"},{"sentence":"I’d appreciate it if you let me get on with my job.","translation":"اگر به من اجازه دهید کارم را ادامه دهم ممنون می شوم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001672079.mp3"}]'::jsonb,3),
('e0f4ea82-f8ac-5a7e-9ac8-1256b7de4221','7dacac78-934d-57c1-a53f-d5ebbcef4ae8',3,null,null,'spoken & written','to understand how good or useful someone or something is','[ transitive ]',null,'برای درک اینکه کسی یا چیزی چقدر خوب یا مفید است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Her abilities are not fully appreciated by her employer.","translation":"توانایی های او به طور کامل توسط کارفرمایش قدردانی نمی شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000944929.mp3"},{"sentence":"I’m not an expert, but I appreciate fine works of art.","translation":"من متخصص نیستم، اما از کارهای هنری خوب قدردانی می کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001672082.mp3"}]'::jsonb,2),
('e311ebbe-4286-571f-b55a-d905ed77d854','7dacac78-934d-57c1-a53f-d5ebbcef4ae8',4,null,null,'technical','to gradually become more valuable over a period of time','[ intransitive ]',null,'تا به تدریج در طی یک دوره زمانی ارزشمندتر شوند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Most investments are expected to appreciate at a steady rate.","translation":"انتظار می رود بیشتر سرمایه گذاری ها با نرخ ثابتی افزایش یابد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000944948.mp3"}]'::jsonb,1),
('39150030-93e8-560b-b493-a5b32ec9f194','06d88e46-b96b-54ab-b38c-a1424a8d366a',1,null,null,'spoken & written','not real or not made of natural things but made to be like something that is real or natural',null,null,'مصنوعی، غیرطبیعی',array['false']::text[],'{}'::text[],array['artificial light/lighting Energy is being wasted by using artificial lighting when daylight is adequate.','artificial sweeteners (= used to make food or drink taste sweeter ) Diet drinks contain artificial sweeteners like saccharin.','artificial colours (= used in food ) I try to buy food that is free from artificial colours.','artificial flavours Ice cream often has artificial flavours in it.','artificial additives (= used to give food more colour or taste ) Artificial additives such as colourings, sweeteners and flavour enhancers aren’t permitted in baby foods.','artificial preservatives (= used to preserve food ) This jam has no artificial preservatives.','artificial flowers a vase of stiff-looking artificial flowers','an artificial environment Animals hate being confined in an artificial environment.','artificial grass artificial grass tennis courts','artificial snow Some ski resorts use huge amounts of artificial snow.','an artificial pitch British English The club is building a new artificial training pitch at its sports ground.']::text[],'[{"sentence":"artificial flowers","translation":"گل مصنوعی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001664181.mp3"},{"sentence":"artificial light","translation":"نور مصنوعی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001664182.mp3"},{"sentence":"artificial fertilizers","translation":"کودهای مصنوعی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000950449.mp3"}]'::jsonb,3),
('be62bd39-9415-5ff4-be45-ec49263ff56b','06d88e46-b96b-54ab-b38c-a1424a8d366a',2,null,null,'spoken & written','an artificial situation or quality exists because someone has made it exist, and not because it is really necessary',null,null,'یک موقعیت یا کیفیت مصنوعی به این دلیل وجود دارد که کسی آن را ایجاد کرده است و نه به این دلیل که واقعاً ضروری است','{}'::text[],'{}'::text[],array['artificial light/lighting Energy is being wasted by using artificial lighting when daylight is adequate.','artificial sweeteners (= used to make food or drink taste sweeter ) Diet drinks contain artificial sweeteners like saccharin.','artificial colours (= used in food ) I try to buy food that is free from artificial colours.','artificial flavours Ice cream often has artificial flavours in it.','artificial additives (= used to give food more colour or taste ) Artificial additives such as colourings, sweeteners and flavour enhancers aren’t permitted in baby foods.','artificial preservatives (= used to preserve food ) This jam has no artificial preservatives.','artificial flowers a vase of stiff-looking artificial flowers','an artificial environment Animals hate being confined in an artificial environment.','artificial grass artificial grass tennis courts','artificial snow Some ski resorts use huge amounts of artificial snow.','an artificial pitch British English The club is building a new artificial training pitch at its sports ground.']::text[],'[{"sentence":"artificial distinctions","translation":"تمایزات مصنوعی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001664183.mp3"},{"sentence":"artificial barriers of gender and race","translation":"موانع مصنوعی جنسیتی و نژادی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001664184.mp3"}]'::jsonb,2),
('f40fd435-08c8-5f0d-ac85-25efd9f16c9e','06d88e46-b96b-54ab-b38c-a1424a8d366a',3,null,null,'spoken & written','artificial behaviour is not sincere – used to show disapproval',null,null,'رفتار مصنوعی صادقانه نیست - برای نشان دادن عدم تایید استفاده می شود','{}'::text[],'{}'::text[],array['artificial light/lighting Energy is being wasted by using artificial lighting when daylight is adequate.','artificial sweeteners (= used to make food or drink taste sweeter ) Diet drinks contain artificial sweeteners like saccharin.','artificial colours (= used in food ) I try to buy food that is free from artificial colours.','artificial flavours Ice cream often has artificial flavours in it.','artificial additives (= used to give food more colour or taste ) Artificial additives such as colourings, sweeteners and flavour enhancers aren’t permitted in baby foods.','artificial preservatives (= used to preserve food ) This jam has no artificial preservatives.','artificial flowers a vase of stiff-looking artificial flowers','an artificial environment Animals hate being confined in an artificial environment.','artificial grass artificial grass tennis courts','artificial snow Some ski resorts use huge amounts of artificial snow.','an artificial pitch British English The club is building a new artificial training pitch at its sports ground.']::text[],'[{"sentence":"an artificial smile","translation":"یک لبخند مصنوعی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000950457.mp3"}]'::jsonb,1),
('c1438044-4adb-5659-b9c5-afa80b583da0','8840ceef-8f0e-5d05-a17a-61cb8c668130',1,null,null,'spoken & written','a process in which you make a judgment about a person or situation, or the judgment you make',null,null,'ارزیابی، سنجش؛ درس‌آزمون','{}'::text[],'{}'::text[],array['make an assessment I had to make a quick assessment of the situation and act accordingly.','do/carry out an assessment A teacher does a yearly assessment of each child’s progress.','a general/overall/broad assessment (= that covers the main features or parts of something, not the details ) The doctor must carry out a general assessment of the patient’s health.','a detailed assessment We need a detailed assessment of what this will cost.','a comprehensive assessment (= that includes all the necessary facts or details ) Our clients receive a comprehensive assessment of their financial affairs.','an objective assessment (= that is based on facts, not on feelings or beliefs ) The test results will provide an objective assessment of how much you have improved.','somebody’s personal assessment What’s your personal assessment of the risks?','the assessment procedure/process Parents need to feel part of the assessment procedure.','assessment methods/techniques We recommend using a variety of assessment methods.']::text[],'[{"sentence":"What’s Michael’s assessment of the situation?","translation":"ارزیابی مایکل از وضعیت چیست؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000922862.mp3"},{"sentence":"a reading assessment test","translation":"آزمون سنجش خواندن","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001744542.mp3"}]'::jsonb,2),
('3506a195-c66a-5f5f-85ee-ab31e26a4323','8840ceef-8f0e-5d05-a17a-61cb8c668130',2,null,null,'spoken & written','a calculation about the cost or value of something',null,null,'محاسبه در مورد هزینه یا ارزش چیزی','{}'::text[],'{}'::text[],array['make an assessment I had to make a quick assessment of the situation and act accordingly.','do/carry out an assessment A teacher does a yearly assessment of each child’s progress.','a general/overall/broad assessment (= that covers the main features or parts of something, not the details ) The doctor must carry out a general assessment of the patient’s health.','a detailed assessment We need a detailed assessment of what this will cost.','a comprehensive assessment (= that includes all the necessary facts or details ) Our clients receive a comprehensive assessment of their financial affairs.','an objective assessment (= that is based on facts, not on feelings or beliefs ) The test results will provide an objective assessment of how much you have improved.','somebody’s personal assessment What’s your personal assessment of the risks?','the assessment procedure/process Parents need to feel part of the assessment procedure.','assessment methods/techniques We recommend using a variety of assessment methods.']::text[],'[{"sentence":"a tax assessment","translation":"یک ارزیابی مالیاتی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000922867.mp3"}]'::jsonb,1),
('56140e71-f683-5581-8dab-1120fc96218c','af2464f4-bb9d-5103-8d68-99d742a3be87',1,null,null,'spoken & written','a piece of work that is given to someone as part of their job','[ countable, uncountable ]',null,'تکلیف، مأموریت؛ واگذاری','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She’s gone to Italy on a special assignment.","translation":"او در یک مأموریت ویژه به ایتالیا رفته است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000923005.mp3"},{"sentence":"He was killed while on assignment abroad.","translation":"او در حین انجام مأموریت در خارج از کشور کشته شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001744567.mp3"}]'::jsonb,2),
('a2eb22f4-6662-5ef1-864b-ae53fa9ad93c','af2464f4-bb9d-5103-8d68-99d742a3be87',2,null,null,'spoken & written','a piece of work that a student is asked to do','[ countable ]',null,'یک قطعه کاری که از دانش آموز خواسته می شود انجام دهد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a history assignment","translation":"یک تکلیف تاریخ","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001984675.mp3"}]'::jsonb,1),
('15b2d3ea-b984-593e-93fd-4c4ffd3d400e','af2464f4-bb9d-5103-8d68-99d742a3be87',3,null,null,'spoken & written','when people are given particular jobs to do','[ uncountable ]',null,'زمانی که به افراد وظایف خاصی داده می شود','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('ff69c21e-a4d4-5d92-9b36-506087e7a326','af2464f4-bb9d-5103-8d68-99d742a3be87',4,null,null,'spoken & written','something such as a place to sit , piece of equipment etc that you are given to use for a particular purpose','[ countable ]',null,'چیزی مانند مکانی برای نشستن، قطعه ای از تجهیزات و غیره که به شما داده می شود تا برای یک هدف خاص از آن استفاده کنید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"an aeroplane seat assignment","translation":"اختصاص صندلی هواپیما","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001744572.mp3"}]'::jsonb,1),
('07c42262-bc4a-5fb0-8eab-7a36fcbec73e','7be7202e-f7e9-5707-baa8-efe81227005a',1,null,null,'spoken & written','help or support',null,null,'کمک، یاری، مساعدت','{}'::text[],'{}'::text[],array['need assistance Phone this number if you need any assistance.','get/receive assistance She got no assistance from her family.','seek assistance If side-effects are severe, seek medical assistance.','give (somebody) assistance Our staff can give assistance with any problems that may arise.','offer assistance I would be grateful for any assistance you can offer.','provide assistance There is no doubt that the US will provide assistance.','pledge/promise assistance A group of donors led by the World Bank promised assistance to the value of US$508,000,000.','ask for/request assistance Police are at the scene and have requested assistance.','financial assistance The company may also provide financial assistance.','economic assistance humanitarian aid and other forms of economic assistance','technical assistance Most of our time is spent providing technical assistance to companies.','legal/medical assistance It was difficult to get good legal assistance.','military assistance Beijing renewed its military assistance to North Korea.','be of assistance (= help ) ‘How can I be of assistance to you?’ she asked.','come to somebody’s assistance (= help someone ) One of her fellow passengers came to her assistance.','turn to somebody for assistance (= ask them to help ) The elderly sometimes have no one to turn to for assistance.']::text[],'[{"sentence":"We offer financial assistance to students.","translation":"ما به دانش آموزان کمک مالی می کنیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001744578.mp3"},{"sentence":"Can I be of any assistance (= can I help you ) ?","translation":"آیا می توانم کمکی داشته باشم (= آیا می توانم به شما کمک کنم)؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001744582.mp3"},{"sentence":"We’ve rebuilt the theatre with the assistance of the National Lottery.","translation":"ما تئاتر را با کمک لاتاری ملی بازسازی کردیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000114.mp3"}]'::jsonb,3),
('10eb7980-c9b0-5713-99c5-26a2c67a81d4','dbfa1c90-1ef7-59a8-af4b-cb1fd28de20c',1,null,null,'spoken & written','something that you think is true although you have no definite proof','[ countable ]',null,'فرض، پیش‌فرض، گمانه','{}'::text[],'{}'::text[],array['make an assumption You’re making a lot of assumptions for which you have no proof.','be based on/rest on an assumption Our plans were based on the assumption that everyone would be willing to help.','work on an assumption (= act according to something that may not be true ) The police seemed to be working on the assumption that he was guilty.','a reasonable/valid assumption This seemed like a reasonable assumption.','a common/general/widespread assumption There’s a common assumption that science is more difficult than other subjects.','a basic/fundamental/underlying assumption There is a basic assumption in international law that a state will protect its citizens.','a correct assumption Many people acted on the correct assumption that interest rates would rise.','a wrong/false/mistaken assumption Both theories are based on a single wrong assumption.','an underlying assumption (= a belief that is used as the basis for an idea, but which may not be correct ) There seems to be an underlying assumption in what he says that women are weaker than men.','a tacit/unspoken assumption (= one that no one says aloud ) There seemed to be a tacit assumption that they would get married.','a questionable assumption (= one that is likely to be wrong ) That assumption was obviously highly questionable.']::text[],'[{"sentence":"A lot of people make the assumption that poverty only exists in the Third World.","translation":"بسیاری از مردم این فرض را دارند که فقر فقط در جهان سوم وجود دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000993945.mp3"},{"sentence":"My calculations were based on the assumption that house prices would remain steady.","translation":"محاسبات من بر این فرض بود که قیمت مسکن ثابت می ماند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001659761.mp3"},{"sentence":"People make a lot of assumptions about me.","translation":"مردم در مورد من فرضیات زیادی می کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001659771.mp3"}]'::jsonb,3),
('9efb603e-1da0-5ba3-b738-eb0d69e98233','dbfa1c90-1ef7-59a8-af4b-cb1fd28de20c',2,null,null,'formal','when someone starts to have control or power','[ uncountable ]',null,'وقتی کسی شروع به کنترل یا قدرت می کند','{}'::text[],'{}'::text[],array['make an assumption You’re making a lot of assumptions for which you have no proof.','be based on/rest on an assumption Our plans were based on the assumption that everyone would be willing to help.','work on an assumption (= act according to something that may not be true ) The police seemed to be working on the assumption that he was guilty.','a reasonable/valid assumption This seemed like a reasonable assumption.','a common/general/widespread assumption There’s a common assumption that science is more difficult than other subjects.','a basic/fundamental/underlying assumption There is a basic assumption in international law that a state will protect its citizens.','a correct assumption Many people acted on the correct assumption that interest rates would rise.','a wrong/false/mistaken assumption Both theories are based on a single wrong assumption.','an underlying assumption (= a belief that is used as the basis for an idea, but which may not be correct ) There seems to be an underlying assumption in what he says that women are weaker than men.','a tacit/unspoken assumption (= one that no one says aloud ) There seemed to be a tacit assumption that they would get married.','a questionable assumption (= one that is likely to be wrong ) That assumption was obviously highly questionable.']::text[],'[{"sentence":"the assumption of responsibility","translation":"قبول مسئولیت","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000993961.mp3"}]'::jsonb,1),
('b6dbae32-c919-548a-b17a-d1d33c82d878','fdb97a03-2efd-52ed-b512-98e38fd0e38f',1,null,null,'spoken & written','(in the Roman Catholic religion ) the bodily taking up of the Virgin Mary (= Jesus'' mother ) into heaven',null,null,'(در مذهب کاتولیک رومی) بردن بدن مریم باکره (= مادر عیسی) به بهشت','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('7dc52a0b-3e04-5d8c-918a-01d3375855dc','fdb97a03-2efd-52ed-b512-98e38fd0e38f',2,null,null,'spoken & written','the day (15 August ) on which this event is celebrated',null,null,'روز (15 اوت) که در آن این رویداد جشن گرفته می شود','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('85526053-e6e1-5f98-b9f3-adeb7890b69d','382c43c2-76a8-5d59-ba31-e43a73369166',1,null,null,'spoken & written','the feeling that an event or place gives you','[ countable, uncountable ]',null,'جوّ، فضای (احساسی)؛ جو زمین','{}'::text[],'{}'::text[],array['a good atmosphere The club has a good atmosphere.','a happy/cheerful atmosphere It''s a good school and it has a very happy atmosphere.','a relaxed/friendly/informal atmosphere Helen''s flat has a very relaxed atmosphere.','a carnival/festive atmosphere (= when people are celebrating something ) Outside the stadium, there was a carnival atmosphere.','a welcoming atmosphere (= when a place you arrive at feels friendly ) The bar provides a welcoming atmosphere for a relaxing evening drink.','a cosy atmosphere (= when a building, room etc is small, comfortable, and warm ) With its low ceilings and open fire, the house has a cosy atmosphere.','a bad atmosphere There''s a bad atmosphere among the staff.','a strained/tense atmosphere (= not relaxed ) As soon as I went in, I was aware of the tense atmosphere in the room.','the atmosphere changes New owners bought the hotel and the whole atmosphere changed.','create a good/bad atmosphere Lighting is one of the most effective ways of creating a good atmosphere.']::text[],'[{"sentence":"The hotel had a lovely relaxed atmosphere .","translation":"هتل یک فضای آرام دوست داشتنی داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000925464.mp3"},{"sentence":"The atmosphere at home was rather tense.","translation":"جو خانه نسبتاً متشنج بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001659568.mp3"},{"sentence":"An atmosphere of optimism dominated the conference.","translation":"فضای خوش‌بینی بر کنفرانس حاکم بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001659571.mp3"}]'::jsonb,3),
