('13fed5c5-229d-5c66-bf1d-5003d2ff7b05','6659a66f-bcaa-532a-acf0-ec6eb5fede74',1,null,null,'spoken & written','a feeling of liking someone, especially in a sexual way','[ countable, uncountable ]',null,'جذبه، کشش؛ جاذبه، دیدنی؛ جذابیت جنسی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The attraction between them was almost immediate.","translation":"جذابیت بین آنها تقریباً فوری بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000997357.mp3"}]'::jsonb,1),
('74c83ced-d853-5d1b-8908-2a7a7341ef6c','6659a66f-bcaa-532a-acf0-ec6eb5fede74',2,null,null,'spoken & written','something interesting or enjoyable to see or do','[ countable ]',null,'چیزی جالب یا لذت بخش برای دیدن یا انجام دادن','{}'::text[],'{}'::text[],array['the main attraction The lovely countryside is obviously the main attraction for visitors.','the star attraction (= someone or something that many people want to see ) The former president was the star attraction of the conference.','a popular attraction The zoo is by far the most popular attraction.','a big/major attraction The ducks and geese are a big attraction to children.','a special attraction A special attraction is the tropical greenhouse.','a tourist attraction The British Museum is one of London’s most popular tourist attractions.','a visitor attraction The park will be a new visitor attraction for the town.','be/become/prove an attraction The organisers hope the event will become an annual attraction.']::text[],'[{"sentence":"The beautiful beaches are the island’s main attraction (= most popular place, activity etc ) .","translation":"سواحل زیبا جاذبه اصلی جزیره (= محبوب ترین مکان، فعالیت و غیره) هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000997368.mp3"}]'::jsonb,1),
('77465e11-30c1-594a-bf7c-aa48515479d6','6659a66f-bcaa-532a-acf0-ec6eb5fede74',3,null,null,'spoken & written','a feature or quality that makes something seem interesting or enjoyable','[ countable, uncountable ]',null,'ویژگی یا کیفیتی که باعث می شود چیزی جالب یا لذت بخش به نظر برسد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Being your own boss is one of the attractions of owning your own business.","translation":"رئیس خود بودن یکی از جذابیت های کسب و کار شخصی شماست.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000997375.mp3"}]'::jsonb,1),
('e212bb57-4f10-5d06-87a5-ff7f271c6991','6659a66f-bcaa-532a-acf0-ec6eb5fede74',4,null,null,'technical','a force which makes things move together or stay together','[ countable, uncountable ]',null,'نیرویی که باعث می شود اشیا با هم حرکت کنند یا با هم بمانند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"the gravitational attraction between the Earth and the Moon","translation":"جاذبه گرانشی بین زمین و ماه","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000124.mp3"}]'::jsonb,1),
('abb2cbc9-59e2-57b5-9f5f-c0b2ea3e4f91','ba8bb3f8-232f-52df-be0b-ef62036b6e3c',1,null,null,'spoken & written','someone who is attractive is good looking, especially in a way that makes you sexually interested in them',null,null,'خوش‌چهره، جذاب، دلفریب','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"an attractive young woman","translation":"یک زن جوان جذاب","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000927174.mp3"},{"sentence":"Women seem to find him attractive .","translation":"به نظر می رسد زنان او را جذاب می دانند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000927177.mp3"}]'::jsonb,2),
('a3baafe5-b116-54da-b128-836884b1124a','ba8bb3f8-232f-52df-be0b-ef62036b6e3c',2,null,null,'spoken & written','pleasant to look at',null,null,'لذت بخش است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Kitchen utensils should be attractive as well as functional.","translation":"ظروف آشپزخانه باید جذاب و همچنین کاربردی باشند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000927181.mp3"}]'::jsonb,1),
('7a886ce7-3fe5-5dd0-a913-13abf84aa728','ba8bb3f8-232f-52df-be0b-ef62036b6e3c',3,null,null,'spoken & written','having qualities that make you want to accept something or be involved in it',null,null,'داشتن ویژگی هایی که باعث می شود شما بخواهید چیزی را بپذیرید یا در آن شرکت کنید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a political movement that is attractive to young people","translation":"یک جنبش سیاسی که برای جوانان جذاب است","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000927192.mp3"},{"sentence":"I must say, it’s a very attractive offer.","translation":"باید بگویم، این یک پیشنهاد بسیار جذاب است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000927195.mp3"}]'::jsonb,2),
('48ee2ce7-e652-5225-9069-87914f14a515','322835a6-6dc7-54ed-bb7b-d3c0f22737f8',1,null,null,'spoken & written','someone’s family, education , previous work etc','[ countable ]',null,'پیشینه، سوابق؛ پس‌زمینه','{}'::text[],'{}'::text[],array['family background Many kids lack a stable family background.','social background Universities aim to attract students from varied social backgrounds.','cultural background Some of his attitudes were due to his cultural background.','ethnic background We do not discriminate against people because of their ethnic background or gender.','class background Class background is an important factor in the level of schooling achieved.','socio-economic background Smokers often come from poorer socio-economic backgrounds.','educational/academic background The interviewer will ask you about your educational background and work experience. Postgraduate students come from a wide range of academic backgrounds.','professional background Managers can come from a wide range of professional backgrounds.','a working-class/middle-class background I came from a very poor working-class background.','a deprived/disadvantaged background The school has a high percentage of pupils from disadvantaged backgrounds.','a poor background His poor background prevented him from going to medical college.','a privileged/wealthy background All the top jobs were taken by people from privileged backgrounds.','have a background (in something) We are looking for someone who has a background in science.','come from a background Mark and I came from very similar backgrounds.','a range of backgrounds People from a wide range of backgrounds go to watch football.']::text[],'[{"sentence":"Students with a background in chemistry will probably find the course easier.","translation":"دانش‌آموزان با پیشینه شیمی احتمالاً درس را راحت‌تر خواهند یافت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001891472.mp3"},{"sentence":"It’s important to understand other people, people from different backgrounds .","translation":"درک افراد دیگر، افراد با پیشینه‌های مختلف، مهم است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001891476.mp3"},{"sentence":"Do you know anything about his background?","translation":"آیا از سابقه او چیزی می دانید؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000134.mp3"}]'::jsonb,3),
