('74b47df4-2fa7-5017-bb37-f2c7e0d686a2','59d164d3-af75-52dd-b9e8-9f55d79e0dda',1,null,null,'spoken & written','to formally ask someone to write an official report , produce a work of art for you etc','[ transitive ]',null,'به طور رسمی از کسی بخواهید که یک گزارش رسمی بنویسد، یک اثر هنری برای شما تولید کند و غیره','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The report was commissioned by the Welsh Office.","translation":"این گزارش به سفارش دفتر ولز تهیه شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000873978.mp3"},{"sentence":"Macmillan commissioned her to illustrate a book by Spike Milligan.","translation":"مک میلان به او سفارش کرد تا کتابی از اسپایک میلیگان را تصویرسازی کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001668923.mp3"}]'::jsonb,2),
