('99d0eddf-7f23-5b2f-9473-c3e524cad737','b394e6f1-c5d6-5cdc-92a0-913eaa7cb26e',1,null,null,'spoken & written','always behaving in the same way or having the same attitudes , standards etc – usually used to show approval',null,null,'ثابت‌قدم، یکنواخت (رفتار)؛ سازگار (داده‌ها)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She’s the team’s most consistent player.","translation":"او ثابت ترین بازیکن تیم است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000856565.mp3"},{"sentence":"We need to be consistent in our approach.","translation":"ما باید در رویکرد خود ثابت قدم باشیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001668026.mp3"}]'::jsonb,2),
('c035fdd5-3e99-5dab-ac47-d82d7061afdc','b394e6f1-c5d6-5cdc-92a0-913eaa7cb26e',2,null,null,'spoken & written','continuing to happen or develop in the same way',null,null,'به همین ترتیب اتفاق می افتد یا توسعه می یابد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a consistent improvement in the country’s economy","translation":"بهبود مستمر در اقتصاد کشور","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000856570.mp3"}]'::jsonb,1),
('3235a529-8fc6-5954-b857-73d04dfe4dfb','b394e6f1-c5d6-5cdc-92a0-913eaa7cb26e',3,null,null,'spoken & written','a consistent argument or idea does not have any parts that do not match other parts',null,null,'یک استدلال یا ایده منسجم هیچ قسمتی ندارد که با سایر بخش‌ها مطابقت نداشته باشد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The evidence is not consistent.","translation":"شواهد سازگار نیست.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001668028.mp3"}]'::jsonb,1),
('0d160614-7a8b-501b-a68a-a391a411daa5','b394e6f1-c5d6-5cdc-92a0-913eaa7cb26e',4,null,null,'spoken & written',null,null,'be consistent with something','ثابت‌قدم، یکنواخت (رفتار)؛ سازگار (داده‌ها)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('a23b5d61-6095-578c-9b6f-9464e045873e','63e370d6-074d-5a9c-8f41-a6505479f0dc',1,null,null,'spoken & written','all the time, or very often',null,null,'به‌طور دائم، مدام، همواره',array['continually']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He talked constantly about his work.","translation":"مدام در مورد کارش صحبت می کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000856897.mp3"},{"sentence":"The English language is constantly changing .","translation":"زبان انگلیسی مدام در حال تغییر است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001668121.mp3"}]'::jsonb,2),
('ace6cb95-735a-551c-83f9-d534884fa3ec','93cba1bd-7191-533a-a4f7-e84fd0b61eb1',1,null,null,'spoken & written','to be considered to be something','[ linking verb ]',null,'تشکیل دادن، به حساب آمدن (به‌عنوان)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Failing to complete the work constitutes a breach of the employment contract.","translation":"عدم تکمیل کار به منزله نقض قرارداد کار است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001668266.mp3"},{"sentence":"The rise in crime constitutes a threat to society.","translation":"افزایش جرم و جنایت تهدیدی برای جامعه است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001105280.mp3"}]'::jsonb,2),
('9dfe7c75-5290-51a4-be5a-c57e5d61d06c','93cba1bd-7191-533a-a4f7-e84fd0b61eb1',2,null,null,'spoken & written','if several people or things constitute something, they are the parts that form it','[ linking verb ]',null,'اگر چند نفر یا چیزها چیزی را تشکیل می دهند، اجزای تشکیل دهنده آن هستند',array['make up']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We must redefine what constitutes a family.","translation":"ما باید دوباره تعریف کنیم که خانواده چه چیزی را تشکیل می دهد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001105271.mp3"},{"sentence":"His letters to his wife make up the middle section of the book.","translation":"نامه های او به همسرش بخش میانی کتاب را تشکیل می دهد.","audio_url":null},{"sentence":"This constitutes a criminal offence.","translation":"این یک جرم کیفری است.","audio_url":null},{"sentence":"Fish products are significant in Japan’s imports, constituting 30% of the total.","translation":"محصولات ماهی در واردات ژاپن قابل توجه است و 30 درصد از کل واردات را تشکیل می دهد.","audio_url":null}]'::jsonb,4),
('44daf8be-d8a1-5224-b519-a759c9f5f8c4','93cba1bd-7191-533a-a4f7-e84fd0b61eb1',3,null,null,'formal','to officially form a group or organization','[ transitive ]',null,'برای تشکیل رسمی یک گروه یا سازمان',array['found']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The Federation was constituted in 1949.","translation":"این فدراسیون در سال 1949 تأسیس شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001668269.mp3"}]'::jsonb,1),
('c8254808-b5dc-5505-b6f2-1d047ce3076d','000361c9-9be2-55cd-9fd5-66fb7f46663c',1,null,null,'spoken & written','continuing to happen or exist without stopping',null,null,'پیوسته، مستمر؛ بی‌وقفه','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"continuous economic growth","translation":"رشد اقتصادی مستمر","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001108830.mp3"},{"sentence":"a continuous flow of information","translation":"یک جریان مداوم اطلاعات","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001108831.mp3"}]'::jsonb,2),
('f87fbcdf-f10d-50cc-9f2c-cb2d34b4d3ba','000361c9-9be2-55cd-9fd5-66fb7f46663c',2,null,null,'spoken & written','something such as a line that is continuous does not have any spaces or holes in it',null,null,'چیزی مانند خطی که پیوسته است، هیچ فاصله یا سوراخی در آن وجود ندارد','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
