('ea76c5f7-c558-540b-808f-7b9493ef0217','000361c9-9be2-55cd-9fd5-66fb7f46663c',4,null,null,'technical','the continuous form of a verb shows that an action is continuing. In English, this is formed by the verb ‘be’, followed by a present participle , as in ‘I was waiting for the bus .’',null,null,'شکل استمراری یک فعل نشان می دهد که یک عمل ادامه دارد. در انگلیسی، این با فعل «be» و به دنبال آن یک فعل حال شکل می‌گیرد، مانند «من منتظر اتوبوس بودم».','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('9e87293c-2e5f-5179-a799-a709533a8797','ec997ea6-258c-5cea-8e94-0ad6d22d6b45',1,null,null,'spoken & written','to give money, help, ideas etc to something that a lot of other people are also involved in','[ intransitive, transitive ]',null,'مشارکت کردن، سهم داشتن؛ سهم دادن (پول، ایده)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"City employees cannot contribute to political campaigns.","translation":"کارمندان شهرداری نمی توانند در مبارزات سیاسی مشارکت کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000860507.mp3"},{"sentence":"The volunteers contribute their own time to the project.","translation":"داوطلبان وقت خود را به پروژه اختصاص می دهند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000860510.mp3"}]'::jsonb,2),
('0779844c-d3fa-50c5-ab04-af88763ae7b1','ec997ea6-258c-5cea-8e94-0ad6d22d6b45',2,null,null,'spoken & written','to help to make something happen','[ intransitive ]',null,'برای کمک به اتفاق افتادن چیزی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Stress is a contributing factor in many illnesses.","translation":"استرس یکی از عوامل موثر در بسیاری از بیماری ها است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001747215.mp3"},{"sentence":"Alcohol contributes to 100,000 deaths a year in the US.","translation":"الکل باعث مرگ 100000 نفر در سال در ایالات متحده می شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000860515.mp3"},{"sentence":"His work contributed substantially to our knowledge of the disease and how to treat it.","translation":"کار او کمک قابل توجهی به دانش ما در مورد این بیماری و نحوه درمان آن کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce6exa_00190.mp3"}]'::jsonb,3),
('fee30dac-64f4-5a43-bb23-03aa66b96911','ec997ea6-258c-5cea-8e94-0ad6d22d6b45',3,null,null,'spoken & written','to write articles , stories, poems etc for a newspaper or magazine','[ intransitive, transitive ]',null,'برای نوشتن مقاله، داستان، شعر و غیره برای یک روزنامه یا مجله','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"one of several authors contributing to the book","translation":"یکی از چندین نویسنده که در این کتاب مشارکت داشته است","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000860521.mp3"}]'::jsonb,1),
('3fc17aee-3928-5ae9-87f3-f1abc3744a64','680a9ad8-790f-5df0-886a-86a5f12302aa',1,null,null,'spoken & written','useful to you because it saves you time, or does not spoil your plans or cause you problems',null,null,'مناسب، به‌صرفه (وقت و کار)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Mail-order catalogs are a convenient way to shop.","translation":"کاتالوگ های پستی راه مناسبی برای خرید هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000861024.mp3"},{"sentence":"My secretary will call you to arrange a convenient time to meet.","translation":"منشی من با شما تماس می گیرد تا یک زمان مناسب برای ملاقات ترتیب دهید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001747311.mp3"},{"sentence":"Is three o''clock convenient for you?","translation":"آیا ساعت سه برای شما مناسب است؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000861027.mp3"},{"sentence":"It is simple and convenient to use.","translation":"استفاده از آن ساده و راحت است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001747316.mp3"},{"sentence":"Is this a good time for you to talk?","translation":"آیا این زمان مناسبی برای صحبت کردن است؟","audio_url":null}]'::jsonb,5),
('a7b5b425-bcb6-5a78-91e5-89d5bc1dc3a5','680a9ad8-790f-5df0-886a-86a5f12302aa',2,null,null,'spoken & written','close and easy to reach',null,null,'نزدیک و دسترسی آسان','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The bus stop around the corner is probably the most convenient.","translation":"ایستگاه اتوبوس در گوشه گوشه احتمالا راحت ترین است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000861034.mp3"},{"sentence":"restaurants convenient for shops and theatres","translation":"رستوران های مناسب برای مغازه ها و تئاتر","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000861037.mp3"}]'::jsonb,2),
('f4e02d2c-32d3-5443-a124-21b272929ab1','ddefb362-ec18-5b7a-a59f-31b7fc19bd9d',1,null,null,'spoken & written','a large formal meeting for people who belong to the same profession or organization or who have the same interests','[ countable ]',null,'کنوانسیون، همایش؛ عرف، رویه؛ پیمان','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a teachers’ convention","translation":"کنوانسیون معلمان","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000861119.mp3"},{"sentence":"the city’s new convention center","translation":"مرکز همایش های جدید شهر","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001747324.mp3"},{"sentence":"a convention for science fiction fans","translation":"همایشی برای طرفداران داستان های علمی تخیلی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001747325.mp3"}]'::jsonb,3),
('9e93b577-f135-5c2e-a615-445ad475cfef','ddefb362-ec18-5b7a-a59f-31b7fc19bd9d',2,null,null,'spoken & written','a formal agreement , especially between countries, about particular rules or behaviour','[ countable ]',null,'یک توافق رسمی، به ویژه بین کشورها، در مورد قوانین یا رفتار خاص',array['pact','treaty']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"the European convention on human rights","translation":"کنوانسیون اروپایی حقوق بشر","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000861108.mp3"}]'::jsonb,1),
('85473d01-cd90-55c4-846e-cd77cf7a96f1','ddefb362-ec18-5b7a-a59f-31b7fc19bd9d',3,null,null,'spoken & written','behaviour and attitudes that most people in a society consider to be normal and right','[ countable, uncountable ]',null,'رفتار و نگرش هایی که اکثر افراد یک جامعه آن را عادی و درست می دانند',array['custom']::text[],'{}'::text[],array['a social/cultural convention Each society has its own cultural conventions.','an established convention (= one that has been used for a long time ) There are established conventions for how you should end a letter.','an accepted convention Saying ''thank you'' and ''please'' is an accepted convention.','defy convention (= not do what is accepted or normal ) At the time she was defying convention by living with a man.','follow convention (= do what is accepted and normal ) If everyone followed convention, the world would be a boring place.','conform to/adhere to convention formal (= do what is accepted and normal ) He’d always chosen not to conform to convention.','flout convention (= deliberately not do what is accepted or normal ) I was determined to flout convention when it came to the funeral arrangements.','a set of conventions In the East you will have to learn a different set of conventions.','rules and conventions Rules and conventions permeate the whole of social life.']::text[],'[{"sentence":"Playing together teaches children social conventions such as sharing.","translation":"بازی با هم به کودکان قراردادهای اجتماعی مانند اشتراک گذاری می آموزد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000861094.mp3"},{"sentence":"They defied the conventions of the time by living together without being married.","translation":"آنها با زندگی مشترک بدون ازدواج، از قراردادهای آن زمان سرپیچی کردند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000861093.mp3"},{"sentence":"By convention, the bride’s father gives her away at her wedding.","translation":"طبق قرارداد، پدر عروس او را در مراسم عروسی خود می دهد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000861097.mp3"}]'::jsonb,3),
('579b999b-5149-54e1-a8e1-b9531233144c','ddefb362-ec18-5b7a-a59f-31b7fc19bd9d',4,null,null,'spoken & written','a method or style often used in literature , art , the theatre etc to achieve a particular effect','[ countable ]',null,'روش یا سبکی که اغلب در ادبیات، هنر، تئاتر و غیره برای دستیابی به یک اثر خاص استفاده می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"the conventions of the 19th-century novel","translation":"قراردادهای رمان قرن نوزدهم","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000366.mp3"}]'::jsonb,1),
('d99f3be6-d63f-53c7-b499-bc79441b2b7f','cacd30ce-5524-5ed7-918b-627010728835',1,null,null,'spoken & written','a very strong belief or opinion','[ countable ]',null,'محکم‌کاری (قضایی)؛ ایمان راسخ، باور','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a woman of strong political convictions","translation":"زنی با اعتقادات سیاسی قوی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000862229.mp3"},{"sentence":"The Dotens have a deep conviction that marriage is for life.","translation":"Dotens اعتقاد عمیقی دارند که ازدواج برای زندگی است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001747400.mp3"},{"sentence":"The students possess the conviction that they can make a difference to their community.","translation":"دانش آموزان این باور را دارند که می توانند در جامعه خود تغییر ایجاد کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001747403.mp3"}]'::jsonb,3),
('75897408-2eae-50c8-823f-4b9bfd6d82ff','cacd30ce-5524-5ed7-918b-627010728835',2,null,null,'spoken & written','the feeling of being sure about something and having no doubts','[ uncountable ]',null,'احساس اطمینان در مورد چیزی و عدم شک و تردید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He was able to say with conviction that he had changed.","translation":"او توانست با قاطعیت بگوید که تغییر کرده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001747406.mp3"},{"sentence":"‘No, ’ she said, without conviction.","translation":"او بدون قانع نشدن گفت: نه.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000862235.mp3"},{"sentence":"It was a reasonable explanation, but his voice lacked conviction .","translation":"توضیح معقولی بود، اما صدای او قانع نبود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000862234.mp3"},{"sentence":"It took her so much effort to speak that what she said carried great conviction (= showed she felt sure of what she said ) .","translation":"آنقدر تلاش او برای صحبت کردن لازم بود که آنچه که او گفت، اعتقاد زیادی داشت (= نشان داد که او از آنچه می گوید مطمئن است).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001747410.mp3"}]'::jsonb,4),
('e0f4ac58-ca0e-5ef7-9689-a560ba27a127','cacd30ce-5524-5ed7-918b-627010728835',3,null,null,'spoken & written','a decision in a court of law that someone is guilty of a crime , or the process of proving that someone is guilty','[ countable, uncountable ]',null,'تصمیم در دادگاه حقوقی مبنی بر مجرم بودن شخصی یا روند اثبات مجرم بودن شخصی','{}'::text[],'{}'::text[],array['a criminal conviction Jason already had a criminal conviction for theft.','a murder/manslaughter/fraud etc conviction He lost his job following a drugs conviction.','a previous/prior conviction (= a crime someone was found guilty of in the past ) The man had five previous convictions for being drunk and disorderly.','a wrongful conviction (= a guilty verdict that was wrong ) The trial led to the men''s wrongful conviction.','have a conviction for something You must declare whether you have any convictions.','lead to a conviction They offered a reward for information leading to the conviction of the killer.','obtain/secure a conviction (= make someone be found guilty ) The prosecution had obtained a conviction based on false evidence.','appeal against conviction (= ask a court of law to change it ) The men intend to appeal against their convictions.','quash/overturn a conviction (= officially say that it was wrong ) The Court of Appeal quashed their convictions.','uphold a conviction (= officially say that it was right ) The conviction was upheld by the Court of Appeal.']::text[],'[{"sentence":"They had no previous convictions.","translation":"آنها سابقه محکومیت قبلی نداشتند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000862245.mp3"},{"sentence":"Applicants are checked for criminal convictions.","translation":"متقاضیان از نظر محکومیت های کیفری بررسی می شوند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001747417.mp3"},{"sentence":"This was her third conviction for theft.","translation":"این سومین محکومیت او به سرقت بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000862248.mp3"},{"sentence":"the trial and conviction of Jimmy Malone","translation":"محاکمه و محکومیت جیمی مالون","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000862254.mp3"}]'::jsonb,4),
('7eaabd23-8187-5c7c-8576-c07478e56f10','65a16486-a527-5371-8f66-d80bd861f545',1,null,null,'spoken & written','without any doubt',null,null,'قطعاً، حتماً، بدون شک',array['certainly']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"‘Do you reckon Margot will be there?’ ‘ Definitely not .’","translation":"\"به نظر شما مارگوت آنجا خواهد بود؟\" \"قطعا نه.\"","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000839719.mp3"},{"sentence":"The hotel fitness centre is definitely worth a visit.","translation":"مرکز تناسب اندام هتل قطعا ارزش بازدید را دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000839718.mp3"},{"sentence":"I definitely need a holiday.","translation":"من قطعا به تعطیلات نیاز دارم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001684286.mp3"}]'::jsonb,3),
